const PORT = Number(process.env.SAGAX_PORT || process.env.OGB_PORT || 8799);
/** Capabilities lot 4: the organization's declarations as last broadcast
 * (public fields): a change tells every open screen to read its
 * capabilities again (configStatus). Declared early: configStatus runs
 * before the organization's modules are built. */
let orgCapabilitiesRevision = "";
const WEBHOOK_PORT = Number(process.env.SAGAX_WEBHOOK_PORT || PORT + 1);
// Behind a proxy or tunnel, the base URL senders should use (docs/self-hosting.md).
// Org stacks set SAGAX_PUBLIC_URL; fall back to it when the dedicated webhook URL is unset.
const WEBHOOK_PUBLIC_URL = resolveWebhookPublicUrl();
const STATIC_DIR = process.env.SAGAX_STATIC_DIR || null;

ensureDirs();
initMediaProxy(DATA_DIR);
// Engine process groups an earlier run left running (a crash, a kill): their
// sub-agents, MCP servers and commands stop now (server/engine-groups.ts).
void reapOrphanEngineGroups(join(DATA_DIR, "engine-groups.json"), { log: (line) => console.log(line) })
  .catch((error) => console.warn(`[engines] leftover process groups not checked: ${error instanceof Error ? error.message : String(error)}`));
/** Public share links for bot templates (server/template-links.ts). */
const templateLinks = new TemplateLinks(DATA_DIR);
/** Pages a bot proposed and the person published (server/published-pages.ts). */
const publishedPages = new PublishedPages(DATA_DIR);
/** Who has a published page open, and its annotations as they change. */
const pageLive = new PageLive();
// The desktop parent owns the primary lease and delegates one private child
// claim; a standalone/headless server owns the primary lease itself. Acquire
// before any durable identity, sessions, config, or Store state is loaded.
const dataDirLease = acquireDataDirLeaseForProcess(DATA_DIR);
let dataDirLeaseReleaseAttempted = false;
function releaseDataDirLeaseAtExit(): void {
  if (dataDirLeaseReleaseAttempted) return;
  dataDirLeaseReleaseAttempted = true;
  try {
    dataDirLease.release();
  } catch (error) {
    // A failed release deliberately leaves a stale, owner-token-protected
    // lease. The next process can recover it only after this PID is dead.
    console.error(`[data-directory] lease release failed: ${error instanceof Error ? error.message : String(error)}`);
  }
}
process.once("exit", releaseDataDirLeaseAtExit);
// Restore before constructing any long-lived config, Store, session or provider
// objects. Replacing files underneath a live Store would overwrite restored data.
let workspaceRestore: WorkspaceRestoreResult = { restored: false };
/** A restore applied at this very start (not the last one on record). */
if (existsSync(join(DATA_DIR, ".backups"))) {
  workspaceRestore = applyPendingWorkspaceRestore(DATA_DIR);
  if (!workspaceRestore.restored && !workspaceRestore.rolledBack) {
    workspaceRestore = readLastWorkspaceRestore(DATA_DIR) ?? workspaceRestore;
  }
}
const workspaceMaintenance = new WorkspaceBackupMaintenance();
// Only after ensureDirs(): it performs the one-time rename of the legacy data
// dir, which must not find a freshly created ~/.sagax already there.
// Remote clients (server/request-auth.ts, server/sessions.ts): a stable identity
// for this server, the paired sessions, and the cookie the served UI uses.
const ENVIRONMENT_ID = loadEnvironmentId(DATA_DIR);
// 2026-10-11: the server log tail of the console's Logs page survives a
// restart, after ensureDirs (server/server-log-ring.ts): a bounded window on disk.
serverLog.persistTo(join(DATA_DIR, "server-log"));
process.once("exit", () => serverLog.flush());
// 2026-10-28: event loop lag (p50/p99/max every minute) and any block over
// 1 s, with the blocked stack when the inspector can read it, in the same
// log (server/event-loop-lag.ts). SAGAX_LOOP_LAG=0 turns it off.
if (process.env.SAGAX_LOOP_LAG !== "0") {
  // console, so the line reaches both docker logs and the log tail (captureConsole).
  startEventLoopLagMonitor({ info: (m) => console.log(m), warn: (m) => console.warn(m) });
}
// Who signs people in here (SAGAX_IDENTITY): a solo server keeps its email
// sign-in list, invitations and mailer; an organization server signs people
// in with Pulsatrix only (Perspicax owns accounts), so the list is empty
// there and a legacy email session ends at its next request.
const IDENTITY = identityConfigFromEnv();
// #1098: an organization server keeps the shared host's ceilings (parallel
// tasks, attachment sizes); a solo server lifts them (server/host-kind.ts).
setSharedHost(IDENTITY.kind === "perspicax");
