/** The security key classes the people who may answer this call's card
 * chose that the call falls in: the bot's owner, and the person the turn
 * speaks for (shared/step-up.ts). Non-empty: Sagax never answers the call
 * itself, the card shows and its Allow needs the key. */
function autoAnswerStepUp(bot: BotRecord, threadId: string, call: Parameters<typeof callStepUpClasses>[0]): StepUpClass[] {
  const classes = callStepUpClasses(call, threadActionClassContext(bot.id, threadId));
  if (!classes.length) return [];
  // the person who answers this thread's cards (a confidential thread's
  // owner, ownerDecision's owner too), not only the bot's owner
  const owner = approvalOwnerId(bot, threadId) || null;
  const out = new Set<StepUpClass>(securityKeys.required(owner, classes, owner));
  const speaker = turnSpeakerPrincipals.get(threadId);
  if (speaker && speaker !== owner) for (const name of securityKeys.required(speaker, classes, owner)) out.add(name);
  return [...out];
}
/** 2026-10-17 (leftovers of #690): the names of the MCP servers a turn of
 * this bot may mount that are not Sagax's own: the configured ones and the
 * personal connections of the owner and of the person the turn speaks for.
 * A tool name one of them could have spelled is never taken for a built-in
 * (sagax-internal-tools.ts foreignToolSpelling). Unreadable sources name
 * nothing more; the registry refuses the reserved names anyway. */
function foreignMcpServerNames(bot: BotRecord, threadId: string): string[] {
  const out = new Set<string>();
  try {
    for (const name of Object.keys(engineMcpServers(bot))) out.add(name);
  } catch {
    // an unreadable configuration names no server
  }
  for (const person of [effectiveBotOwner(bot), turnSpeakerPrincipals.get(threadId)]) {
    if (!person || !isPrincipalId(person)) continue;
    try {
      for (const name of Object.keys(personConnections.servers(person))) out.add(name);
    } catch {
      // a vault that does not open names no server
    }
  }
  return [...out];
}
/** Organization server (org-full-access.ts): the admin policy, on unless
 * an admin turned it off in Settings > Organization. */
function orgFullAccessPolicy(): boolean {
  return orgFullAccessAllowed(cfg.organization);
}
/** 2026-10-14 (bot owner permissions): an MCP server whose tools act
 * through a person's identity elsewhere for this bot's turn: Sagax's own
 * Perspicax mounts (`perspicax_*`, the person's tokens; Perspicax applies
 * DAP and profile holds), a
 * remote server mounted for the bot, or a personal connection of the owner
 * or of the person the turn speaks for (it runs in their own environment).
 * A host-level built-in is never one (engine-access.ts). */
function ownerScopedMcpServerFor(bot: BotRecord, threadId: string): (server: string) => boolean {
  return (server) => {
    const name = server.toLowerCase();
    if (name.startsWith("perspicax_")) return true;
    if (claudeAiOwnerScopedServer(server, turnAccessByThread.get(threadId)?.via)) return true;
    const has = (names: Iterable<string>) => [...names].some((candidate) => candidate.toLowerCase() === name);
    try {
      if (has(Object.entries(engineMcpServers(bot)).filter(([, spec]) => "url" in spec).map(([key]) => key))) return true;
    } catch {
      // an unreadable configuration names no server
    }
    for (const person of [effectiveBotOwner(bot), turnSpeakerPrincipals.get(threadId)]) {
      if (!person || !isPrincipalId(person)) continue;
      try {
        if (has(Object.keys(personConnections.servers(person)))) return true;
      } catch {
        // a vault that does not open names no server
      }
    }
    return false;
  };
}

/** Whether the owner route may run as "bypass" at Full access: not once
 * the organization's Full access policy went off, or the owner's profile
 * lost bots.fullAccess (Full then reads as Approve for me). */
function ownerBypassAllowed(bot: BotRecord, ownerId: string): boolean {
  if (IDENTITY.kind !== "perspicax") return true;
  if (!orgFullAccessPolicy()) return false;
  if (botOwnerOrgRole(bot) === "admin") return true;
  return isPrincipalId(ownerId) && can(principalPermissions(ownerId, { sessionAdmin: false }), "bots.fullAccess");
}

/** The person who may manage approval rules and modes on this request:
 * a signed-in person or this computer's own operator, never a local
 * service or a turn's token. */
function ruleManager(auth: RequestAuth): string | null {
  // a bot's act copy of its person's session is the bot, not the person:
  // it never saves, edits or removes a rule, nor changes a mode
  // unless it replays a change the person allowed on its card (sagax_settings)
  if (auth.kind === "session" && isBotActSession(auth.session) && actConfirmed()?.personKey !== personKey(auth.session)) return null;
  const id = approvalCallerUserId(auth);
  return id ? id : null;
}

// ── security key step-up (wave 2, package E) ───────────────────────────
/** Every answer path asks this before an Allow goes anywhere
 * (server/step-up-gate.ts). A path that cannot carry a step-up (a Live
 * call, the console, an AI client) passes none and is refused for a card
 * that needs one: never let through silently. */
function stepUpGate(person: string | null, threadId: string, requestId: string, behavior: string, answer: StepUpAnswer, stepUp: unknown): StepUpDecision {
  const message = store.messagesFor(threadId).find((row) => row.card?.requestId === requestId);
  const card = message?.card;
  const context = threadActionClassContext(botForApproval(threadId, message ?? {})?.id, threadId);
  const act = card?.botActRequest ? botActStepUpContent(requestId) : undefined;
  return approvalStepUp({
    keys: securityKeys, person, policyPerson: stepUpPolicyPerson(threadId, message),
    threadId, requestId, card, behavior, answer, risks: card ? cardRiskClasses(card, context) : [], stepUp,
    ...(act ? { extraClasses: act.classes, extraContent: act.content } : {}),
  });
}

/** 2026-10-17: the thread's own folder, against which a file write is
 * judged (shared/step-up.ts actionToolClasses): a write there is
 * irreversible, one that may replace a file anywhere else destructive too. */
function threadActionClassContext(botId: string | undefined, threadId: string): ReturnType<typeof actionClassContext> {
  // an id that is not one plain folder name names no folder of its own
  const plain = (value: string) => /^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$/.test(value) && !value.includes("..");
  return actionClassContext(botId && plain(botId) && plain(threadId) ? [join(TASK_WORKSPACES_DIR, botId, threadId)] : []);
}

/** Whose chosen classes apply when nobody answers as a person: the bot's
 * owner. */
function stepUpPolicyPerson(threadId: string, message: { from?: { botId?: string }; card?: { destinationAnswerer?: unknown } } | undefined): string | null {
  const bot = botForApproval(threadId, message ?? {});
  return bot ? cardAnswererId(bot, threadId, message?.card) || null : null;
}

/** A bot act card holds no route of its own: its classes and content come
 * from the waiting act (a delete is destructive, any write in a class; gone
 * is in a class too). */
function botActStepUpContent(requestId: string): { classes: ReturnType<typeof botActClasses>; content: unknown } {
  const target = botActs().target(requestId);
  const planned = botActs().plannedClasses(requestId).filter((name): name is StepUpClass => (STEP_UP_CLASSES as readonly string[]).includes(name));
  const classes = botActClasses(target);
  return { classes: STEP_UP_CLASSES.filter((name) => classes.includes(name) || planned.includes(name)), content: target ?? null };
}

/** A standing grant (Always allow) saved from a card: its own grant of the
 * same step-up. */
function alwaysAllowStepUpGate(person: string | null, botId: string, threadId: string, requestId: string, key: string, stepUp: unknown): StepUpDecision {
  const message = store.messagesFor(threadId).find((row) => row.card?.requestId === requestId);
  const card = message?.card;
  return alwaysAllowStepUp({ keys: securityKeys, person, policyPerson: stepUpPolicyPerson(threadId, message), botId, threadId, requestId, card, key, risks: card ? cardRiskClasses(card, threadActionClassContext(botId, threadId)) : [], stepUp });
}

/** An approval level made looser needs the person's key when they chose
 * "rule-change" (and "always-grant" when a refresh brings Always allow
 * keys): a step-up for exactly this operation, bot, thread and level, or
 * the one-time allowance a step-up left for it (the desktop's trusted
 * channel carries none). `op`: bot, thread, refresh, all-threads, new-task;
 * `thread`: a thread id or "*". `froms`: every level the change replaces
 * (all threads of a bot, for "all-threads"). */
function approvalModeStepUpGate(input: {
  person: string | null; botId: string; op: string; thread: string; froms: Array<string | undefined>; to: string;
  stepUp?: unknown; allowance?: unknown; widensAllow?: boolean;
}): StepUpDecision {
  const classes: StepUpClass[] = [];
  const loosens = input.froms.some((from) => approvalModeLoosens(from, input.to));
  if (loosens) classes.push("rule-change");
  // Full answers every call, whatever its class (2026-10-17, re-review of
  // #690): entering it needs the key when the person protects any class.
  if (loosens && input.to === "full") for (const name of STEP_UP_CLASSES) if (!classes.includes(name)) classes.push(name);
  if (input.widensAllow) classes.push("always-grant");
  if (!classes.length) return null;
  if (actConfirmedCovers(classes)) return null;
  const bot = store.bot(input.botId);
  const required = securityKeys.required(input.person, classes, bot ? approvalOwnerId(bot) || null : null);
  if (!required.length) return null;
  if (!input.person) return { status: 403, body: { error: "A looser approval level needs the person's security key.", code: "step_up_required", classes: required } };
  if (input.allowance !== undefined && securityKeys.takeAllowance(input.allowance, input.person, approvalModeAllowanceKey(input.op, input.botId, input.thread, input.to))) return null;
  return settingsStepUp(securityKeys, input.person, "approval-mode", { op: input.op, botId: input.botId, thread: input.thread, mode: input.to }, input.stepUp, required);
}

/** 2026-10-16: a change of a member's bot to Auto or Auto-accept edits
 * while the organization does not allow them (member-auto-approval.ts).
 * Checked before approvalModeStepUpGate, which still asks the key when the
 * organization allows them. */
function memberAutoRefused(bot: { ownerUserId?: unknown }, froms: Array<string | undefined>, to: string): boolean {
  return memberAutoChangeRefused({ memberOwned: memberOwnedInOrg(bot), policyAllowed: memberAutoApprovalAllowed(cfg.organization), froms, to });
}

function approvalModeAllowanceKey(op: string, botId: string, thread: string, mode: string): string {
  return `approval-mode\n${op}\n${botId}\n${thread}\n${mode}`;
}

/** The levels an all-threads change replaces: the bot's and each thread's. */
function everyThreadMode(bot: BotRecord): string[] {
  return [approvalModeFor(bot), ...store.tasks(bot.id).map((task) => approvalModeFor(store.projectBotForTask(bot.id, task.threadId) ?? bot))];
}

/** A refresh copies the bot's saved level and Always allow keys onto one
 * thread: what it would widen. */
function refreshWidens(botId: string, threadId: string): { from: string; to: string; widensAllow: boolean } | null {
  const bot = store.bot(botId);
  const current = store.projectBotForTask(botId, threadId);
  if (!bot || !current) return null;
  const to = approvalModeFor({ ...bot, approvalGrant: undefined });
  const widensAllow = (bot.alwaysAllow ?? []).some((key) => !(current.alwaysAllow ?? []).includes(key));
  return { from: approvalModeFor(current), to, widensAllow };
}

function stepUpAnswerOf(body: Record<string, unknown> | null | undefined): StepUpAnswer {
  return {
    always: body?.always === true,
    rememberCommand: body?.rememberCommand === true,
    rule: body?.rule === "allow" || body?.rule === "deny" ? body.rule : null,
  };
}

/** A settings change that loosens a protection: the person's key when they
 * chose the class that protects it. */
function settingsStepUpGate(person: string | null, action: StepUpSettingsAction, detail: Record<string, unknown>, stepUp: unknown, policyPerson?: string | null): { status: number; body: StepUpRefusal } | null {
  const protectedBy = SETTINGS_ACTION_CLASS[action];
  if (!protectedBy) return null;
  if (actConfirmedCovers([protectedBy])) return null;
  const required = securityKeys.required(person, [protectedBy], policyPerson);
  if (!required.length) return null;
  if (!person) return { status: 403, body: { error: "This change needs the person's security key.", code: "step_up_required", classes: required } };
  return settingsStepUp(securityKeys, person, action, detail, stepUp, required);
}

/** 2026-10-19 ("Toujours permettre" on every card): whether this person
 * still answers this kind of strict card: an admin's card of a member's bot
 * for an organization admin or a holder of host.shell; a holder's server
 * command for the bot's current owner who still holds host.commands. */
function strictRuleQualifies(personId: string, bot: BotRecord, kind: "admin" | "holder"): boolean {
  const id = personId.trim().toLowerCase();
  if (!id || !isPrincipalId(id)) return false;
  const person = principals.byId(id);
  if (!person || person.disabledAt !== undefined) return false;
  if (kind === "holder") return id === effectiveBotOwner(bot).trim().toLowerCase() && principalCan(id, "host.commands");
  return person.local === true || person.orgRole === "admin" || principalCan(id, "host.shell");
}

/** Review of #938: an organization admin (or the local operator), signed
 * in and not disabled, by their principal id. */
function workspaceAdminPrincipal(personId: string): boolean {
  const id = personId.trim().toLowerCase();
  if (!id || !isPrincipalId(id)) return false;
  const person = principals.byId(id);
  return Boolean(person && person.disabledAt === undefined && (person.local === true || person.orgRole === "admin"));
}

/** The allow rule saved on an admin's card of this bot that answers this
 * call now: its person still holds the right and protects none of the
 * call's classes with a security key. */
function strictCardRule(
  bot: BotRecord,
  threadId: string,
  call: { botId: string; tool: string; input?: string; cwd?: string },
  kind: "admin" | "holder",
  stepUpCall: Parameters<typeof callStepUpClasses>[0],
): OwnerRule | undefined {
  // review of #938: a rule kept before main fixed it with the fingerprint
  // of no arguments (an engine's shell line reported beside no input)
  // covered every command of the bot: it answers nothing. An empty scope is
  // only ever its person's explicit "any target" (PATCH anyTarget).
  const rules = ownerApprovals.adminRulesForBot(bot.id).filter((rule) => (!Object.keys(rule.scope).length || scopeRemembers(rule.scope)) && strictRuleQualifies(rule.ownerId, bot, kind));
  if (!rules.length) return undefined;
  const classes = callStepUpClasses(stepUpCall, threadActionClassContext(bot.id, threadId));
  for (const rule of rules) {
    if (classes.length && securityKeys.required(rule.ownerId, classes, rule.ownerId).length) continue;
    const match = matchOwnerRule([rule], { ownerId: rule.ownerId, ...call });
    if (match) return match;
  }
  return undefined;
}

/** 2026-10-19 ("Toujours permettre" on every card): the Always allow
 * the person who answers this bot's cards kept for a card that is not an
 * engine's own tool call (a held action, a send, a proposal), the very same
 * scope key for key; none while a security key of theirs protects one of
 * the classes, or on a guest's turn. */
function keptCardRule(bot: BotRecord, threadId: string, candidate: { tool: string; scope: Record<string, string> }, classes: readonly StepUpClass[] = []): OwnerRule | undefined {
  if (cloudGuestDriven(threadId) || botmailConfined(threadId)) return undefined;
  const answerer = approvalOwnerId(bot, threadId);
  if (!answerer) return undefined;
  if (classes.length && securityKeys.required(answerer, [...classes], answerer).length) return undefined;
  return ownerApprovals.rulesOf(answerer, bot.id).find((rule) => rule.botId === bot.id && ruleCoversExactScope(rule, candidate.tool, candidate.scope));
}

/** What Always allow keeps on a proposal card (a routine, a profile, a
 * model): its kind and target, in plain words, and the security key
 * classes the proposal is in. */
function proposalRuleCandidate(card: NonNullable<Message["card"]> | undefined): { tool: string; scope: Record<string, string>; description: string; classes: StepUpClass[] } | undefined {
  const operation = card?.routineRequest?.operation;
  if (operation) {
    const routineId = "routineId" in operation ? operation.routineId : undefined;
    const name = routineId ? routines?.listRoutines().find((row) => row.id === routineId)?.name : undefined;
    const forBot = operation.forBot?.botId;
    const verb: Record<string, string> = { create: "Create routines", update: "Change", pause: "Pause", resume: "Resume", run_now: "Run now", delete: "Delete" };
    return {
      tool: "sagax:routine",
      scope: { action: operation.action, ...(routineId ? { routine: routineId } : {}), ...(forBot ? { for: forBot } : {}) },
      description: operation.action === "create"
        ? `Create routines${forBot ? ` for ${store.bot(forBot)?.name ?? "another bot"}` : ""}`
        : `${verb[operation.action] ?? "Change"} the routine${name ? ` "${name}"` : ""}`,
      classes: operation.action === "delete" ? ["destructive"] : operation.action === "run_now" || operation.action === "pause" ? [] : ["always-grant"],
    };
  }
  const profile = card?.profileRequest;
  if (profile) {
    const fields = Object.keys(profile.changes ?? {}).sort();
    return {
      tool: "sagax:profile",
      scope: { target: profile.targetBotId, fields: fields.join(",") },
      description: `Change ${fields.join(", ") || "the profile"} of ${store.bot(profile.targetBotId)?.name ?? profile.targetName}`,
      classes: [],
    };
  }
  const model = card?.modelRequest;
  if (model) {
    return {
      tool: "sagax:model",
      scope: { target: model.targetBotId, model: `${model.selection.instanceId}/${model.selection.model}` },
      description: `Switch ${store.bot(model.targetBotId)?.name ?? model.targetName} to ${model.selection.model}`,
      classes: [],
    };
  }
  return undefined;
}

/** A proposal card just shown: Always allow's scope goes on the card, and a
 * rule the person kept settles it at once (journaled). Returns the
 * resolution when a rule settled it. */
function settleProposalByRule<T extends { claimed: boolean }>(
  bot: BotRecord,
  threadId: string,
  proposed: { requestId: string; messageId: string },
  resolve: (args: { botId: string; threadId: string; requestId: string; behavior: "allow" }) => T,
): { rule: OwnerRule; result: T } | undefined {
  const message = store.messagesFor(threadId).find((row) => row.id === proposed.messageId);
  const card = message?.card;
  if (!message || !card || card.answered || card.dismissed) return undefined;
  const candidate = proposalRuleCandidate(card);
  if (!candidate) return undefined;
  store.patchMessage(threadId, message.id, { card: { ...card, ownerRule: { tool: candidate.tool, scope: candidate.scope, description: candidate.description } } });
  const kept = keptCardRule(bot, threadId, candidate, candidate.classes);
  if (!kept) return undefined;
  const result = resolve({ botId: bot.id, threadId, requestId: proposed.requestId, behavior: "allow" });
  if (!result.claimed) return undefined;
  const settled = store.messagesFor(threadId).find((row) => row.id === message.id);
  if (settled?.card) store.patchMessage(threadId, message.id, { card: { ...settled.card, ruleSaved: { id: kept.id, behavior: kept.behavior, description: kept.description } } });
  appendDecision(DATA_DIR, {
    threadId, requestId: proposed.requestId, botId: bot.id, botName: bot.name, tool: card.tool, summary: card.subtitle,
    decision: "auto-approved", source: "owner-rule", rule: kept.id,
  });
  return { rule: kept, result };
}

function strictRuleOwnerName(personId: string): string {
  const person = principals.byId(personId.trim().toLowerCase());
  return person?.name?.trim() || person?.email?.trim() || "an admin";
}

/** "Always allow" or "Always deny" on a card: save the owner's rule before
 * the answer goes out, so the bot's next ask already meets it. Null when
 * the body asks for no rule; otherwise the refusal. */
function saveOwnerRuleFromCard(auth: RequestAuth, threadId: string, requestId: string, rule: unknown, behavior: string, ruleScope?: unknown): { status: 400 | 403 | 404 | 409 | 500 | 503; error: string } | null {
  if (rule === undefined || rule === null) return null;
  if (rule !== "allow" && rule !== "deny") return { status: 400, error: "rule must be allow or deny" };
  if (rule !== behavior) return { status: 400, error: "Always allow allows and Always deny denies." };
  const message = store.messagesFor(threadId).find((row) => row.card?.requestId === requestId);
  const card = message?.card;
  if (!message || !card) return { status: 404, error: "No such approval." };
  if (ruleScope !== undefined && ruleScope !== null && ruleScope !== "exact" && ruleScope !== "folder") return { status: 400, error: "ruleScope must be exact or folder" };
  // 2026-10-26 (#1065): "folder" keeps the card's folder rule (every file
  // of the folder and its subfolders), only an allow, only where the card
  // offered it. An ordinary card has no `from`. An admin card offers the
  // folder only for a read of one agent root (`from: "admin"`, no writes).
  const wholeFolder = ruleScope === "folder";
  if (wholeFolder) {
    const folder = card.ownerRuleFolder;
    const ordinary = rule === "allow" && Boolean(folder) && card.ownerRule?.from === undefined;
    const adminRead = rule === "allow" && folder?.from === "admin" && folder.writes !== true && card.ownerRule?.from === "admin";
    if (!ordinary && !adminRead) {
      return { status: 409, error: "This approval cannot be remembered for the whole folder." };
    }
  }
  if (!card.ownerRule || card.answered || card.dismissed || card.expired) {
    return { status: 409, error: "This approval cannot be remembered as a rule." };
  }
  const bot = botForApproval(threadId, message);
  if (!bot) return { status: 404, error: "No such approval." };
  const caller = ruleManager(auth);
  // 2026-10-19 an admin's card is remembered by the person who answers
  // it (an admin, a holder of host.shell, or the owner holding
  // host.commands for their own bot's server command), as their own rule
  // for this bot; an Always deny there answers nothing (the card stays).
  // Always deny only where it answers something (shared/approval-rule-card.ts)
  if (rule === "deny" && !alwaysDenyOffered(card) && card.ownerRule.from !== "admin") return { status: 400, error: "On this card, only Always allow is remembered." };
  const strict = card.adminApproval === true || card.serverCommandHolder === true;
  if (strict) {
    if (card.ownerRule.from !== "admin") return { status: 409, error: "This approval cannot be remembered as a rule." };
    if (rule !== "allow") return { status: 400, error: "On an admin's card, only Always allow is remembered." };
    if (!caller || !strictRuleQualifies(caller, bot, card.adminApproval ? "admin" : "holder")) {
      return { status: 403, error: "Only a person who answers this card can save a rule for it." };
    }
  }
  const ownerId = strict ? caller! : cardAnswererId(bot, threadId, card);
  if (!caller || caller.toLowerCase() !== ownerId.toLowerCase()) return { status: 403, error: "Only the bot owner can save a rule." };
  const candidate: NonNullable<typeof card.ownerRule> = wholeFolder ? card.ownerRuleFolder! : card.ownerRule;
  // 2026-10-21 (review of #938): an empty scope is the whole tool, and the
  // fingerprint of no arguments every such call: never saved from a card
  // ("any target" stays an explicit edit of one's own rule)
  if (!scopeRemembers(candidate.scope)) return { status: 409, error: "This approval cannot be remembered as a rule." };
  let saved: OwnerRule;
  try {
    saved = ownerApprovals.add({
      ownerId, botId: bot.id, tool: candidate.tool, scope: candidate.scope,
      ...(candidate.destructive ? { destructive: candidate.destructive } : {}),
      ...(candidate.from ? { from: candidate.from } : {}),
      behavior: rule, description: candidate.description,
    });
  } catch (error) {
    const status = (error as { status?: number }).status;
    return { status: status === 409 || status === 503 ? status : 500, error: error instanceof Error ? error.message : String(error) };
  }
  store.patchMessage(threadId, message.id, { card: { ...card, ruleSaved: { id: saved.id, behavior: saved.behavior, description: saved.description } } });
  orgAudit({
    category: "approval", action: "approval.rule.save", target: auditBotTarget(bot.id),
    after: { rule: saved.id, behavior: saved.behavior, tool: saved.tool },
    actor: orgAuditActor(auth),
  });
  return null;
}

function botsOwnedBy(personId: string): BotRecord[] {
  const me = personId.toLowerCase();
  return store.bots.filter((bot) => effectiveBotOwner(bot).toLowerCase() === me);
}

/** Remove a legacy Allow key from the bot and every conversation of it. */
function revokeLegacyKey(bot: BotRecord, key: string): void {
  store.patchBot(bot.id, { alwaysAllow: (bot.alwaysAllow ?? []).filter((entry) => entry !== key) });
  for (const task of bot.tasks ?? []) {
    if (task.alwaysAllow?.includes(key)) store.patchTask(bot.id, task.threadId, { alwaysAllow: task.alwaysAllow.filter((entry) => entry !== key) });
  }
  const live = store.bot(bot.id);
  if (live) broadcast({ kind: "bot", bot: wireBot(live) });
}

/** 2026-10-11: the level a new bot starts on. A solo server keeps Approve
 * for me; an organization server follows its policy (`defaults.approvalMode`)
 * and starts on Ask when it names none. */
/** The language a new bot greets its person in (#1075): on an organization
 * server the owner's own language preference (kept per person), then the
 * server's language, the same default the app falls back to. */
function newBotGreetingLanguage(ownerUserId: string | undefined): "fr" | "en" {
  let person = "";
  try {
    if (IDENTITY.kind === "perspicax" && ownerUserId) person = userPreferenceStore.get(ownerUserId).preferences["omb-language"] ?? "";
  } catch { /* no preference of their own */ }
  return greetingLanguage([person, cfg.language]);
}
function newBotApprovalMode(): "ask" | "auto" {
  return IDENTITY.kind === "perspicax" ? orgNewBotApprovalMode(cfg.newBotDefaults?.profile.approvalMode) : "auto";
}
/** Organization server: a stored Full that may not run as Full now (the
 * policy is off, or the bot's current owner never confirmed it). Never on
 * a solo server, where the desktop's private channel grants Full. */
function orgDeniesFull(bot: { ownerUserId?: unknown; fullAccessConsent?: unknown }): boolean {
  return IDENTITY.kind === "perspicax" &&
    !orgFullAccessHolds({ policyAllowed: orgFullAccessPolicy(), ownerPrincipalId: effectiveBotOwner(bot), consent: bot.fullAccessConsent });
}
/** The signed-in person making a request; null for loopback or a service. */
