function videoInputMessage(capability: InternalCapabilityView): Message | undefined {
  const current = [...internalCapabilities.values()].find(item => item.kind === "agents" && item.botId === capability.botId && item.threadId === capability.threadId && item.generation === capability.generation);
  const request = directRequestOwners.get(capability.threadId);
  return videoSourceMessage({ messages: store.activePath(capability.threadId),
    messageId: request?.generations.has(capability.generation) ? request.messageId : undefined,
    startedAt: current?.turnStartedAt ?? 0,
    principalId: IDENTITY.kind === "perspicax" ? turnMediaPrincipal(capability.threadId) : undefined,
    routine: turnRoutineLineage.has(capability.threadId) || Boolean(request?.automation),
  });
}
function videoScopeValid(scope: VideoScope): boolean {
  const bot = store.bot(scope.botId);
  if (!bot || bot.hidden) return false;
  const group = store.groupByThread(scope.threadId);
  if (!(store.taskByThread(bot.id, scope.threadId) || bot.threadId === scope.threadId || group?.memberIds.includes(bot.id))) return false;
  if (IDENTITY.kind !== "perspicax") return true;
  return Boolean(providerAccountOwner(scope.principalId)) && viewerMayAnswerOnThread(scope.threadId, scope.principalId);
}
const videoJobsDir = join(DATA_DIR, "video-jobs");
// Register the context before opening a journal sealed on an earlier run.
registerAtRestRoot({ id: "video-jobs", dir: videoJobsDir, context: path => `video-jobs/${path}`, files: () => videoGenerations.files() });
const videoGenerations = new VideoGenerations({
  dir: videoJobsDir,
  provider: createXaiVideoProvider(videoFixtureUrl ? { baseUrl: videoFixtureUrl } : {}),
  valid: videoScopeValid,
  credential: async (scope, payer) => {
    if (!videoScopeValid(scope)) throw new VideoJobError("This conversation or its person is no longer available.", 404);
    const owner = providerAccountOwner(scope.principalId);
    return videoCredential({
      organization: IDENTITY.kind === "perspicax",
      personal: () => owner ? providerAccounts.resolve(owner, "xai") : Promise.resolve({ ok: false, error: "user_inactive" }),
      solo: () => providerAccounts.key(undefined, "xai"),
      organizationAllowed: () => orgXaiMediaGiven("image", scope.principalId),
      organizationKey: () => cfg.xai?.key,
    }, payer);
  },
  read: path => readAtRestSync(path).toString("utf8"),
  written: (path, job) => noteAtRestWrite(path, { thread: job.scope.threadId }),
  save: async (url, job, signal) => {
    const upstream = await openGeneratedVideo(url, signal, videoFixtureUrl ? { policy: mediaProxyPolicyFromEnv({ SAGAX_MEDIA_PROXY_ALLOW_HOSTS: "127.0.0.1" }) } : {});
    try {
      const saved = await saveFile(generatedMp4Chunks(upstream, signal), "Generated video.mp4", "video/mp4", {
        uploadId: job.id, owner: job.scope.principalId,
        ...(upstream.headers["content-length"] ? { expectedBytes: Number(upstream.headers["content-length"]) } : {}),
      });
      return { ...saved, mime: "video/mp4" };
    } finally { upstream.destroy(); }
  },
  // The MP4 takes the place of the job's status row, so the person sees one
  // row go from progress to the video. Idempotent by saved path.
  publish: job => {
    if (!videoScopeValid(job.scope)) throw new VideoJobError("This conversation or its person is no longer available.", 404);
    const bot = store.bot(job.scope.botId)!;
    const messages = store.activePath(job.scope.threadId);
    const attachments = [{ kind: "file" as const, path: job.saved.path, name: job.saved.name, mime: job.saved.mime }];
    const existing = messages.find(message => message.role === "bot" && message.attachments?.some(file => file.path === job.saved.path));
    const statusRow = !existing && job.messageId ? messages.find(message => message.id === job.messageId) : undefined;
    const message = existing
      ?? (statusRow ? store.patchMessage(job.scope.threadId, statusRow.id, { kind: "text", text: "", widget: undefined, attachments }) : null)
      ?? store.appendMessage(job.scope.threadId, {
        role: "bot", kind: "text", text: "", attachments,
        ...(store.groupByThread(job.scope.threadId) ? { from: { botId: bot.id, name: bot.name, color: bot.color } } : {}),
      });
    return `/api/threads/${job.scope.threadId}/files/${threadFileId(message.id, job.saved.path)}`;
  },
  // Progress, Stop and failure receipts in the conversation itself: the
  // person never has to ask the bot whether a video is still coming.
  show: job => {
    if (!videoScopeValid(job.scope)) return undefined;
    const bot = store.bot(job.scope.botId);
    if (!bot) return undefined;
    const row = videoStatusRow(job, languageOfPerson(job.scope.principalId === "solo" ? null : job.scope.principalId));
    const room = store.groupByThread(job.scope.threadId);
    const shape = room
      ? { kind: "text" as const, text: row.text, from: { botId: bot.id, name: bot.name, color: bot.color } }
      : { kind: "widget" as const, text: row.text, widget: { v: 1 as const, root: row.root } };
    const current = job.messageId ? store.activePath(job.scope.threadId).find(message => message.id === job.messageId) : undefined;
    if (current) return store.patchMessage(job.scope.threadId, current.id, shape)?.id ?? current.id;
    return store.appendMessage(job.scope.threadId, { role: "bot", ...shape }).id;
  },
});

/** The OpenAI or ElevenLabs keys that may serve one person's voice, in the
 * order of the xAI keys (server/voice-mode.ts resolveVoiceKeys): their own
 * voice key (My voice keys), their own OpenAI key in Perspicax, then the
 * organization's key when it was given to them (the same grant as its xAI
 * voice). A solo server: the server's key. Never sent anywhere but to the
 * provider. */
async function voiceProviderKeys(provider: Exclude<VoiceTtsProvider, "xai">, speaker: VoiceSpeaker): Promise<VoiceKeyCandidate[]> {
  if (speaker.disabled) return [];
  if (provider === "system" || provider === "chatterbox") {
    const available = provider === "system" ? systemVoicesAvailable() : Boolean(cfg.tts?.baseUrl?.trim());
    return available ? [{ key: `local-${provider}`, via: "server", source: "server", last4: null, provider }] : [];
  }
  const serverKey = (provider === "openai" ? cfg.openai?.key : provider === "fish" ? cfg.tts?.fishKey : voiceCredential(cfg.tts?.key)?.token)?.trim();
  if (IDENTITY.kind !== "perspicax") {
    const key = await providerAccounts.key(undefined, provider).catch(() => undefined) || serverKey;
    return key ? [{ key, via: "server", source: "server", last4: keyLast4(key), provider }] : [];
  }
  if (speaker.disabled || !speaker.principalId) return [];
  const keys: VoiceKeyCandidate[] = [];
  const owner = providerAccountOwner(speaker.principalId);
  const personal = owner ? await providerAccounts.key(owner, provider).catch(() => undefined) : undefined;
  if (personal) keys.push({ key: personal, via: "speaker-key", source: "perspicax-key", last4: keyLast4(personal), payerPrincipalId: speaker.principalId, provider });
  const grant = provider === "elevenlabs" ? ELEVENLABS_VOICE_SERVER_ENGINE : provider === "fish" ? FISH_VOICE_SERVER_ENGINE : VOICE_SERVER_ENGINE;
  if (serverKey && serverEngineAllowedFor(speaker.principalId, grant)) keys.push({ key: serverKey, via: "org-key", source: "org-key", last4: keyLast4(serverKey), provider });
  return keys;
}

// Voice mode (server/voice-mode.ts): xAI speech to text and text to speech
// for the floating voice bar, with the speaker's own xAI key (Perspicax),
// else the server's xAI key (Settings > Models and voice, xai.key; since
// 2026-10-14 Grok voice has no key of its own). The key never leaves the
// server; the spoken turn itself goes through the normal send route.
const voiceModeDeps: VoiceModeDeps = {
  organization: IDENTITY.kind === "perspicax",
  notice: (threadId, message) => publishVoiceNotice(threadId, message),
  speaker: (auth) => {
    if (auth.kind === "loopback" && auth.trust === "service") return null;
    const principalId = actorPrincipalId(auth);
    if (IDENTITY.kind !== "perspicax") return { principalId };
    const person = principalId && isPrincipalId(principalId) ? principals.byId(principalId) : null;
    if (!person) return { principalId: "" };
    const sub = person.subject?.iss === IDENTITY.issuer ? person.subject.sub : undefined;
    return { principalId, ...(sub ? { sub } : {}), ...(person.disabledAt !== undefined && person.disabledAt !== null ? { disabled: true } : {}) };
  },
  target: (auth, botId, threadId) => {
    const bot = store.bot(botId);
    if (!bot) return { status: 404, error: "no such bot" };
    if (IDENTITY.kind === "perspicax") {
      const viewerId = actorPrincipalId(auth);
      const viewer = authzViewerFromId(viewerId);
      if (!viewer || !canOnBot(viewer, "bot.use", botFacts(bot))) return { status: 404, error: "no such bot" };
      if (threadId && (!store.taskByThread(bot.id, threadId) || !botThreadReadable(bot, threadId, viewerId, "thread.post"))) {
        return { status: 404, error: "no such conversation" };
      }
      // a call named no thread: the person's one conversation (the rule the
      // desktop and the phone read), where its turns show up as they happen
      return { botId: bot.id, botName: bot.name, threadId: threadId ?? conversationOrStart(bot, viewerId) ?? viewerThreadOf(bot, viewerId) ?? bot.threadId, ownerPrincipalId: effectiveBotOwner(bot) };
    }
    return { botId: bot.id, botName: bot.name, threadId: threadId ?? conversationOrStart(bot) ?? bot.threadId };
  },
  serverKey: () => IDENTITY.kind === "perspicax" ? cfg.xai?.key : providerAccounts.key(undefined, "xai"),
  hasOwnKey: () => IDENTITY.kind === "perspicax",
  // 2026-10-16 the organization's xAI key gives voice only to the
  // people Perspicax lists it for (an admin always).
  serverKeyAllowed: (speaker) => serverEngineAllowedFor(speaker.principalId, VOICE_SERVER_ENGINE),
  resolveOwnKey: (sub) => {
    const person = IDENTITY.kind === "perspicax" ? principals.bySubject(IDENTITY.issuer, sub) : null;
    const owner = providerAccountOwner(person?.id);
    return owner ? providerAccounts.resolve(owner, "xai") : Promise.resolve({ ok: false as const, error: "no_key" as const });
  },
  keysUrl: () => perspicaxKeysUrl(),
  isAdmin: (auth) => orgAdminCaller(auth),
  xai: {
    listVoices: grokVoice.listVoices,
    synthesize: grokVoice.synthesize,
    transcribe: grokVoice.transcribe,
    synthesizeStream: grokVoice.synthesizeStream,
    openTranscription: (key, options, handlers) => grokVoice.openTranscriptionStream(key, options, handlers),
    openSpeech: (key, options, handlers) => grokVoice.openSpeechStream(key, options, handlers),
    warm: (key) => void grokVoice.listVoices(key).catch(() => {}),
  },
  // OpenAI and ElevenLabs (2026-10-29): the person picks who speaks and who
  // hears in Settings > Voice and Edit bot > Voice; each falls back on the
  // others (server/voice-mode.ts)
  openai: openAiVoiceMode,
  elevenlabs: elevenLabsVoiceMode,
  fish: fishVoiceMode,
  ...installedVoices,
  legacyChoice: () => ({ provider: tts.voiceProvider(cfg), voice: cfg.tts?.voice }),
  providerKeys: (provider, speaker) => voiceProviderKeys(provider, speaker),
  preference: (speaker) => {
    if (IDENTITY.kind !== "perspicax" || !speaker.principalId || !isPrincipalId(speaker.principalId)) return undefined;
    const raw = userPreferenceStore.get(speaker.principalId).preferences[VOICE_MODE_STORAGE_KEY];
    if (typeof raw !== "string") return undefined;
    try { return JSON.parse(raw) as unknown; } catch { return undefined; }
  },
  upgrade: (req) => desktopViewer.upgradeOf(req),
  utterances: toUtterances,
  keyterms: (target, speaker) => {
    const person = speaker.principalId && isPrincipalId(speaker.principalId) ? principals.byId(speaker.principalId) : null;
    const viewer = IDENTITY.kind === "perspicax" ? authzViewerFromId(speaker.principalId) : null;
    const otherBotNames = store.bots
      .filter((bot) => bot.id !== target.botId && (IDENTITY.kind !== "perspicax" || (viewer && canOnBot(viewer, "bot.use", botFacts(bot)))))
      .map((bot) => bot.name);
    // target() already checked this person may read the thread
    const recentTexts = store.messagesTail(target.threadId, VOICE_KEYTERM_RECENT_MESSAGES).messages
      .filter((message) => message.kind === "text" && typeof message.text === "string")
      .map((message) => message.text as string);
    return voiceKeyterms({
      botName: target.botName,
      ...(person?.name ? { personName: person.name } : {}),
      otherBotNames,
      configured: configuredKeyterms(process.env.SAGAX_VOICE_KEYTERMS),
      recentTexts,
    });
  },
  callSession: {
    start: (target, callId, language, auth, heartbeat) => {
      voiceCalls.start(target.threadId, callId, language, heartbeat === true);
      if (!auth) return;
      const bot = store.bot(target.botId);
      if (!bot) return;
      // Every start and heartbeat (about every 5 minutes, under sandboxd's
      // 10 minute idle stop) counts as use of the server environment this
      // call's turns work in (the one startTurn picks), so a call never
      // loses it between two questions. Starts nothing.
      if (userSandbox) {
        const person = sandboxPrincipalForTurn({
          botOwnerPrincipalId: effectiveBotOwner(bot), confidentialOwnerPrincipalId: confidentialThreadOwner(target.threadId), routine: false, speakerPrincipalId: orgSpeakerPrincipal(bot, speakerFor(auth)),
        })?.trim().toLowerCase();
        if (person) void userSandbox.markUsed(person, bot.id);
      }
      voiceWarmup.begin(target.threadId, callId, (signal) => new Promise<void>((resolve) => {
        void startTurn(bot.id, "", {
          threadId: target.threadId,
          warmOnly: true,
          warmSignal: signal,
          speaker: speakerFor(auth),
          voiceCall: { callId, ...(language && language !== "auto" ? { language } : {}) },
          onWarmSettled: () => resolve(),
        }).catch((error) => {
          console.error(`[voice-call] warm skipped: ${error instanceof Error ? error.name : "error"}`);
          resolve();
        });
      }));
    },
    end: (target, callId, auth) => {
      // Drop the call first so a warm that is still retiring does not keep
      // its Perspicax tokens. Then close the idle process. Other devices
      // of this person hang up from the frame.
      if (!voiceCalls.end(target.threadId, callId)) return;
      voiceWarmup.cancel(target.threadId, callId);
      releaseWarmEngine(target.threadId);
      void perspicaxMcp?.endWarm(target.threadId);
      broadcastVoiceCallEnded(target.threadId, callId, "person", auth);
    },
    heard: (target, callId, audio) => {
      if (voiceCalls.active(target.threadId)?.callId !== callId) return;
      voiceLatency.heard(target.threadId, audio);
    },
  },
  assertWithinBudget: () => assertWithinBudget(cfg, DATA_DIR),
  recordUsage: (usage) => {
    const bot = store.bot(usage.target.botId);
    const row: UsageRow = {
      at: new Date().toISOString(),
      botId: usage.target.botId,
      botName: usage.target.botName,
      threadId: usage.target.threadId,
      instanceId: `${usage.provider ?? "xai"}Voice`,
      driverKind: `${usage.provider ?? "xai"}-voice`,
      model: usage.model,
      input: usage.input,
      output: 0,
      // xAI reports no price here: an estimate, so voice counts toward the spend limits
      costUsd: voiceCostUsd(usage.model, usage.input),
      costSource: "estimated" as const,
      trigger: usage.speaker.principalId && IDENTITY.kind === "perspicax" ? { kind: "user", principalId: usage.speaker.principalId } : { kind: "owner" },
      ...(IDENTITY.kind === "perspicax" ? { access: usage.via, ...(bot ? { ownerPrincipalId: effectiveBotOwner(bot) } : {}) } : {}),
      ...(usage.payerPrincipalId ? { payerPrincipalId: usage.payerPrincipalId } : {}),
    };
    noteSpend(DATA_DIR, row, appendUsage(DATA_DIR, row));
  },
};
ROUTES.push(createVoiceModeRoutes(voiceModeDeps));

// The caller's own claude.ai connectors, read through their own Claude
// account (server/harness-connectors.ts); always on, no server switch.
const claudeAiInventory = new ClaudeAiConnectorInventory({ run: runClaudeCli });
/** The CLI and environment of a person's own Claude account (their
 * claude.ai connectors), or why there is none. */
function claudeAccountForPrincipal(principalId: string): { cli: string; env: NodeJS.ProcessEnv; key: string } | { unavailable: "no_engine" | "not_signed_in" | "key" } {
  const entries = Object.entries(instanceConfigs(cfg)).filter(([, entry]) => entry.driver === "claudeAgent");
  const [instanceId, entry] = entries.find(([id]) => id === "claude") ?? entries[0] ?? [];
  if (!instanceId || !entry) return { unavailable: "no_engine" as const };
  const config = (entry.config ?? {}) as { cli?: unknown; configDir?: unknown };
  const cli = typeof config.cli === "string" && config.cli.trim() ? config.cli : "claude";
  const env: NodeJS.ProcessEnv = { ...process.env, ...entry.environment };
  if (IDENTITY.kind === "perspicax") {
    if (!engineLogins?.signedIn(principalId, "claudeAgent")) return { unavailable: "not_signed_in" as const };
    env.CLAUDE_CONFIG_DIR = engineLogins.loginDir(principalId, "claudeAgent");
    delete env.ANTHROPIC_API_KEY;
    delete env.ANTHROPIC_AUTH_TOKEN;
    return { cli, env, key: `person:${principalId}` };
  }
  // A custom API instance has no claude.ai account. A separate provider key
  // never hides the subscription account's connectors.
  if (entry.environment?.ANTHROPIC_API_KEY) return { unavailable: "key" as const };
  if (typeof config.configDir === "string" && config.configDir.trim()) {
    try {
      env.CLAUDE_CONFIG_DIR = resolveClaudeConfigDir(config.configDir, env);
    } catch {
      return { unavailable: "no_engine" as const };
    }
  }
  return { cli, env, key: `instance:${instanceId}` };
}

// "Connect Microsoft Teams" cards (server/routes/connector-setup.ts): the
// person who asked checks theirs; Claude's inventory is read again.
ROUTES.push(createConnectorSetupRoutes({
  ...connectorSetupStore(),
  principalId: (auth) => {
    if (auth.kind === "loopback" && auth.trust === "service") return undefined;
    return actorPrincipalId(auth) || (IDENTITY.kind === "solo" ? localPrincipalId() : undefined);
  },
  claudeConnectors: async (principalId) => {
    if (IDENTITY.kind === "solo" && principalId !== localPrincipalId().trim().toLowerCase()) return null;
    const account = claudeAccountForPrincipal(principalId);
    if ("unavailable" in account) return null;
    const inventory = await claudeAiInventory.read(account.key, { cli: account.cli, env: account.env }, true);
    return inventory.auth === "subscription" ? inventory.connectors : null;
  },
}));
/** The setup cards of a conversation and the calls that prove one (server/routes/connector-setup.ts). */
function connectorSetupStore() {
  return {
    cards: (threadId: string) => store.messagesFor(threadId).flatMap((message) => message.connectorSetup ? [{ messageId: message.id, view: message.connectorSetup }] : []),
    proofs: () => connectorSetupProofs,
    botOf: (threadId: string) => store.botByThread(threadId)?.id,
    patch: (threadId: string, messageId: string, view: ConnectorSetupView) => { store.patchMessage(threadId, messageId, { connectorSetup: view }); },
    // the person's own Grok sign-in folder, as their turns run it (engine-credentials.ts)
    grokReach: (principalId: string) => {
      const reach = grokAccountReach(principalLoginDir(principalId, "grokAgent"));
      // 2026-10-29: the person's second Grok sign-in, when that one has it
      const second = engineLogins?.signedIn(principalId, "grokAgent", "second") ? grokAccountReach(principalLoginDir(principalId, "grokAgent", "second")) : undefined;
      const elsewhere = second?.connectors.length
        ? { engine: relayAccountLabel(driverDisplayName("grokAgent"), grokAccountKindFor(principalId, "second")), connectors: second.connectors }
        : undefined;
      // 2026-10-30: which account the card's connector goes on
      const account = grokAccountKindFor(principalId, "primary");
      if (!reach && !elsewhere && !account) return undefined;
      return { connectors: reach?.connectors ?? [], at: reach?.at ?? 0, ...(elsewhere ? { elsewhere } : {}), ...(account ? { account } : {}) };
    },
  };
}
/** The person a sign-in card is for: the one speaking, never a routine or a peer. */
function connectorSetupSpeaker(threadId: string): string | undefined {
  const speaker = turnSpeakers.get(threadId);
  if (!speaker || (speaker.origin !== "person" && speaker.origin !== "operator")) return undefined;
  const bot = store.bots.find((candidate) => candidate.threadId === threadId) ?? store.bots.find((candidate) => store.taskByThread(candidate.id, threadId));
  return connectorPrincipalFor({ identity: IDENTITY.kind, speaker, ownerPrincipalId: bot ? effectiveBotOwner(bot) : "", localPrincipalId: localPrincipalId() }) || undefined;
}
/** The bot's engine and whose account it runs on for this turn (#943). */
function connectorSetupContext(botId: string, threadId: string): ConnectorSetupContext | null {
  // the engine this conversation runs on, which may not be the bot's default
  const bot = store.projectBotForTask(botId, threadId) ?? store.bot(botId);
  const instance = bot ? registry.get(bot.modelSelection.instanceId) : undefined;
  const speaker = turnSpeakers.get(threadId);
  if (!bot || !instance || !speaker) return null;
  const driver = instance.driverKind;
  // 2026-10-28: the person's own Grok or Claude sign-in on another engine
  // this bot may run (run_with_engine), so a card never dead-ends on "this
  // engine can't attach connectors to your own account".
  const ownOn = (drivers: readonly string[]) => registry.instances().some((candidate) =>
    candidate.enabled && drivers.includes(candidate.driverKind)
    && accountConnectorsForTurn(accountConnectorInput(bot, candidate, speaker)) === "own");
  return {
    engine: driver === "claudeAgent" ? "claude" : driver === "grokAgent" || driver === "grok" ? "grok" : "other",
    account: accountConnectorsForTurn(accountConnectorInput(bot, instance, speaker, turnAccessByThread.get(threadId)?.via)),
    ownAccounts: { grok: ownOn(["grokAgent", "grok"]), claude: ownOn(["claudeAgent"]) },
  };
}

