// The engines' own slash commands in the chat (server/harness-commands.ts):
// listed by the engine itself in the folder and isolation the bot's turns
// get, passed through verbatim when typed.
const harnessCommands = new HarnessCommandCatalog();
/** What makes the list the SPEAKER's (server/harness-commands.ts): on an
 * organization server their own subscription (from the turn's access, else
 * the planned one, never a key read), and whether the turn keeps the
 * claude.ai connectors of that account. */
function harnessCommandAccount(
  bot: BotRecord,
  instance: { instanceId: string; driverKind: string },
  speaker: TurnSpeaker,
  access?: TurnAccess,
): Pick<HarnessCommandScope, "access" | "claudeAiConnectors"> {
  let listing = commandListAccess(access);
  let via = access?.via;
  if (IDENTITY.kind === "perspicax" && !access) {
    const plan = resolveEngineAccess(orgEngineInput(bot, instance, speaker));
    if (plan.ok) {
      via = plan.via;
      const payer = plan.payerPrincipalId;
      if (plan.via === "subscription" && payer && (instance.driverKind === "claudeAgent" || instance.driverKind === "codex")) {
        const dir = principalLoginDir(payer, instance.driverKind);
        listing = { via: "subscription", identity: `subscription:${payer}`, ...(instance.driverKind === "claudeAgent" ? { claudeConfigDir: dir } : { codexHome: dir }) };
      }
    }
  }
  const connectors = claudeAiConnectorsFor(bot, instance, speaker, via);
  return { ...(listing ? { access: listing } : {}), ...(connectors ? { claudeAiConnectors: true } : {}) };
}
/** The folder a group's turn runs in for this member, without pinning it
 * (the pin happens at the first turn, see runGroupMemberTurn). */
function groupCommandCwd(bot: BotRecord, instance: { driverKind: string }, group: GroupRecord, threadId: string): string | undefined {
  if (!supportsWorkspaceFiles(instance.driverKind)) return undefined;
  const pinned = group.dm ? group.pinnedCwd : store.groupTaskByThread(group.id, threadId)?.pinnedCwd;
  return (pinned !== undefined ? pinned : group.cwd) ?? ensureWorkspace(bot.id);
}
interface HarnessCommandSourceOptions {
  /** A turn's own scope (its folder and isolation). */
  scope?: HarnessCommandScope;
  /** Whose list it is: their subscription and connectors (organization). */
  speaker?: TurnSpeaker;
  /** The turn's materialized access, when there is one already. */
  access?: TurnAccess;
  /** The bot as a member of this group (`threadId` is the group's). */
  group?: GroupRecord;
}
function harnessCommandSource(bot: BotRecord, threadId: string | undefined, options: HarnessCommandSourceOptions = {}): HarnessCommandSource | null {
  // the bot keeps its own engine wherever it works (upstream #2220)
  const instance = registry.get(bot.modelSelection.instanceId);
  const engine = instance ? harnessEngineFor(instance.driverKind) : null;
  if (!instance?.listCommands || !engine) return null;
  let cwd: string | undefined;
  if (options.group) cwd = threadId ? groupCommandCwd(bot, instance, options.group, threadId) : undefined;
  else {
    const task = threadId ? store.taskByThread(bot.id, threadId) : undefined;
    // the folder the thread's next turn runs in (see the pin in runTurn)
    cwd = task && task.cwd !== undefined ? task.cwd ?? undefined
      : bot.cwd ?? (task && threadId && supportsWorkspaceFiles(instance.driverKind) ? ensureTaskWorkspace(bot.id, threadId) : undefined);
  }
  const list = instance.listCommands.bind(instance);
  const account = options.speaker ? harnessCommandAccount(bot, instance, options.speaker, options.access) : {};
  return {
    botId: bot.id,
    instanceId: instance.instanceId,
    engine,
    scope: {
      ...(options.scope ?? {
        botId: bot.id,
        ...(cwd ? { cwd } : {}),
        ...(withholdHostToolsFor(instance) ? { withholdHostTools: true } : {}),
        mcpFromUserConfig: claudeUserMcpEnabled(cfg, IDENTITY.kind === "perspicax") && !managedPolicy.restrictsMcp(),
        ...pluginDirsFor(bot, instance, options.speaker ? orgSpeakerPrincipal(bot, options.speaker) : undefined),
      }),
      ...account,
    },
    list,
  };
}
/** Whose command list a request reads: the signed-in person, else the
 * operator at this computer. */
function harnessCommandSpeaker(auth: RequestAuth): TurnSpeaker {
  const viewerId = actorPrincipalId(auth);
  return viewerId ? { origin: "person", principalId: viewerId } : { origin: "operator" };
}
ROUTES.push(createHarnessCommandRoutes({
  catalog: harnessCommands,
  sourceFor: (auth, botId, threadId, groupId) => {
    const bot = store.bot(botId);
    if (!bot) return { status: 404, error: "no such bot" };
    const viewerId = actorPrincipalId(auth);
    const speaker = harnessCommandSpeaker(auth);
    if (groupId) {
      // A member of a group the caller posts in: its commands for that group.
      // Listing starts the engine (a CLI run on the caller's subscription),
      // so it takes channel.post like the send does, not only channel.read.
      const group = store.group(groupId);
      if (!group || group.peopleDm || !group.memberIds.includes(bot.id)) return { status: 404, error: "no such group" };
      if (IDENTITY.kind === "perspicax") {
        const channelViewer = channelViewerId(auth);
        if (!groupVisible(group, channelViewer)) return { status: 404, error: "no such group" };
        if (!groupPostAllowed(group, channelViewer)) return { status: 403, error: "you may read this channel, not post in it" };
      }
      const groupThread = threadId ?? group.threadId;
      const ownsThread = group.dm ? group.threadId === groupThread : Boolean(store.groupTaskByThread(group.id, groupThread));
      if (!ownsThread) return { status: 404, error: "no such conversation" };
      return harnessCommandSource(bot, groupThread, { group, speaker });
    }
    if (threadId && !store.taskByThread(bot.id, threadId)) return { status: 404, error: "no such conversation" };
    if (IDENTITY.kind === "perspicax") {
      const viewer = authzViewerFromId(viewerId);
      if (!viewer || !canOnBot(viewer, "bot.use", botFacts(bot))) return { status: 404, error: "no such bot" };
      if (threadId && !botThreadReadable(bot, threadId, viewerId, "thread.post")) return { status: 404, error: "no such conversation" };
    }
    return harnessCommandSource(bot, threadId ?? (IDENTITY.kind === "perspicax" ? viewerThreadOf(bot, viewerId) : bot.threadId), { speaker });
  },
}));

// Invite links (/join#token=...): public like /api/auth/email/start, and
// counted against the same per-source lockout as pairing. Security model:
// server/org-routes.ts `joinInviteRoute`.
const publicInvites = createPublicInviteRoutes({
  state: orgState,
  ownerEmail: () => (orgState.org ? principalEmail(orgState.org.ownerUserId) : undefined),
  limiter: {
    source: requestSource,
    allowed: (source) => sessions.attemptAllowed(source),
    noteFailure: (source) => sessions.noteFailure(source),
    clearFailures: (source) => sessions.clearFailures(source),
  },
  persist: () => persistOrgState(),
  signIn: ({ req, res, email }) => {
    const principal = principals.forAccount({ email });
    const issued = sessions.issue({ label: `Invited: ${email}`, scopes: ["client"], email, principalId: principal.id });
    const secure = requestOrigin(req)?.startsWith("https://") === true;
    res.setHeader("set-cookie", serializeSessionCookie(SESSION_COOKIE, issued.token, { secure, maxAgeSeconds: cookieMaxAgeSeconds(issued.session) }));
  },
});

// "Sign in with Pulsatrix" (server/oidc-login.ts), only on an organization
// server. One relying party serves the sign-in routes, the grant refreshes
// and the back-channel logout; the grants live in a sealed vault
// (server/idp-session.ts).
const oidcRp = IDENTITY.kind === "perspicax"
  ? new OidcRelyingParty({ issuer: IDENTITY.issuer, clientId: IDENTITY.clientId, redirectUri: IDENTITY.redirectUri, resource: IDENTITY.publicOrigin, ...(IDENTITY.internalBase ? { internalBase: IDENTITY.internalBase } : {}) })
  : null;
let idpVaultKey: ReturnType<typeof resolveIdpVaultKey> | null = null;
// One vault holds the sign-in grants and the routine delegations (slice 6).
const idpVault = oidcRp ? new IdpGrantVault(DATA_DIR, () => (idpVaultKey ??= resolveIdpVaultKey(DATA_DIR))) : null;
// Slice 6, fix 2: every revocation at Perspicax is durable and paced by the
// relying party's budget (SAGAX_PERSPICAX_TOKEN_BUDGET); pending ones resume here.
const idpRevocations = oidcRp
  ? new RevocationQueue({
    dataDir: DATA_DIR,
    keySource: () => (idpVaultKey ??= resolveIdpVaultKey(DATA_DIR)),
    pacer: oidcRp.pacer,
    send: (token, hint) => oidcRp.revokeAttempt(token, hint),
  })
  : null;
if (oidcRp && idpRevocations) {
  oidcRp.setRevocations(idpRevocations);
  idpRevocations.start();
}
// 2026-10-18: the sign-in again an account deletion needs (memory only); an
// unused one is revoked at Perspicax when it expires.
const accountReauth = oidcRp
  ? new AccountReauth({ revoke: (token, hint, why) => idpRevocations?.enqueue(token, hint, why) })
  : null;
if (accountReauth) {
  setInterval(() => accountReauth.sweep(), 60_000).unref();
  sessions.onSessionRevoked((sessionId) => accountReauth.forgetSession(sessionId));
}
/** 2026-10-20: one line per 401 for a presented session and per session the
 * server ends (server/auth-refusal-log.ts). */
const authRefusals = createAuthRefusalLogger();
const headerText = (value: string | string[] | undefined): string | undefined => Array.isArray(value) ? value[0] : value;
const idpSessions = oidcRp && idpVault
  ? new IdpSessionManager({
    vault: idpVault,
    rp: oidcRp,
    sessions,
    principals,
    refreshAfterMs: refreshAfterMs(process.env.SAGAX_OIDC_REFRESH_AFTER_SECONDS),
    teamNames: (teams) => { orgTeams.mergeFromClaims(teams); },
    ...(idpRevocations ? { revocations: idpRevocations } : {}),
    // 2026-10-08: while the person keeps using Sagax, their routine
    // delegation is issued or slid with their session.
    onRenewed: (subject, access) => {
      const person = principals.bySubject(subject.iss, subject.sub);
      if (person && person.disabledAt === undefined) void routineConsents?.keepAlive(person.id, access);
    },
  })
  : null;
if (oidcRp && idpVault) {
  routineConsents = new RoutineConsents({
    vault: idpVault,
    rp: oidcRp,
    principals,
    renewMs: routineRenewMs(process.env.SAGAX_ROUTINE_RENEW_SECONDS),
    ...(idpRevocations ? { revocations: idpRevocations } : {}),
    onEnded: routineConsentEnded,
    onActive: (principalId) => {
      routineAudit("routine_delegation.granted", principalId);
      routines?.resumeFor(principalId, (routine) => effectiveRunAs({ botId: routine.botId }));
    },
    // 2026-10-08 issued from the person's sign-in, never asked.
    issue: (token) => perspicaxDirectory
      ? perspicaxDirectory.issueRoutineDelegation(token)
      : Promise.resolve({ ok: false as const, error: "link" as const }),
    sessionSubject: (principalId) => {
      const person = principals.byId(principalId);
      if (!idpSessions || !person?.subject || person.disabledAt !== undefined) return Promise.resolve({ ok: false as const, error: "no_session" as const });
      return idpSessions.subjectToken({ iss: person.subject.iss, sub: person.subject.sub });
    },
    subjectOf: (principalId) => {
      const person = principals.byId(principalId);
      return person?.subject && IDENTITY.kind === "perspicax" && person.subject.iss === IDENTITY.issuer && person.disabledAt === undefined
        ? { iss: person.subject.iss, sub: person.subject.sub }
        : null;
    },
  });
}
// A "Sign in with Pulsatrix" session kept across an unclean restart needs the
// provider to confirm it; without one to ask, it ends as before.
if (!idpSessions) {
  const dropped = sessions.dropPendingRechecks();
  if (dropped) console.log(`sessions: ${dropped} sign-in(s) kept across a restart ended (no identity provider to confirm them)`);
}
if (idpSessions) {
  const unavailable = idpSessions.unavailableReason();
  if (unavailable) console.error(`sign-in with Pulsatrix is unavailable: ${unavailable}`);
  // Any session that ends takes its grant with it (logout, a device revoked
  // by an admin, expiry). A back-channel logout drops its grants first, so
  // nothing is sent back to the provider there.
  sessions.onSessionRevoked((sessionId) => idpSessions.release(sessionId, { revokeAtIdp: true }));
  // A desktop or phone sign-in's pairing credential became a session.
  sessions.onExchanged((session) => {
    if (session.idp?.grantRef) idpSessions.bindSession(session.idp.grantRef, session.id);
  });
  try {
    const swept = idpSessions.sweep();
    if (swept) console.log(`sign-in with Pulsatrix: revoked ${swept} grant(s) left without a session`);
  } catch (error) {
    console.error(`sign-in with Pulsatrix: the grant sweep failed: ${error instanceof Error ? error.message : String(error)}`);
  }
  setInterval(() => {
    try { idpSessions.sweep(); } catch { /* retried on the next tick */ }
  }, IDP_SWEEP_INTERVAL_MS).unref();
  // 2026-10-20: a refresh a stop interrupted (its answer, a rotated token,
  // may be lost) is sent again now, inside Perspicax's reuse grace.
  idpSessions.resumeInterrupted();
}
// The Perspicax directory (slice 3): read with the link token Perspicax
// writes to SAGAX_PERSPICAX_LINK_FILE. Keeps the principals current and logs
// out people Perspicax disabled or deleted, even when no back-channel push
// arrived. Without the file, sign-in works and the share picker is empty.
if (IDENTITY.kind === "perspicax" && oidcRp && idpSessions && process.env.SAGAX_PERSPICAX_LINK_FILE?.trim()) {
  const intervalMs = directoryIntervalMs(process.env.SAGAX_PERSPICAX_DIRECTORY_SECONDS);
  let version = "0.0.0";
  try {
    version = String((JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")) as { version?: unknown }).version ?? version);
  } catch {
    /* the header then says 0.0.0 */
  }
  const manager = idpSessions;
  perspicaxDirectory = new PerspicaxDirectory({
    issuer: IDENTITY.issuer,
    serverBase: oidcRp.serverOrigin(),
    linkFile: process.env.SAGAX_PERSPICAX_LINK_FILE.trim(),
    expect: { issuer: IDENTITY.issuer, publicOrigin: IDENTITY.publicOrigin, clientId: IDENTITY.clientId },
    principals,
    teamNames: orgTeams,
    // 2026-10-28: the person a link call acts for, next to the link token.
    subjectToken: (sub) => perspicaxLinkSubjectToken(sub),
    onPersonOut: (iss, sub) => {
      perspicaxMcp?.forgetSubject(iss, sub);
      routineConsents?.endForSubject(iss, sub);
      const done = manager.backchannelLogout({ iss, sub });
      console.log(`perspicax directory: a person is out; ${done.sessions} session(s) ended, ${done.pairings} pairing code(s) cancelled`);
    },
    onRoleNarrowed: (principalId) => {
      const narrowed = manager.narrowToOrgRole(principalId, "member");
      if (narrowed) console.log(`perspicax directory: a demotion narrowed ${narrowed} session(s)`);
    },
    // Slice 7: the organization audit names the link it reads.
    onLinkChanged: (previous, next) => orgAudit({
      category: "org", action: next ? "org.link" : "org.unlink", target: { kind: "link", ...(next ?? previous ? { id: (next ?? previous)!.serverId } : {}) },
      ...(previous ? { before: { serverId: previous.serverId } } : {}),
      ...(next ? { after: { serverId: next.serverId, issuer: IDENTITY.issuer } } : {}),
      actor: { kind: "worker" },
    }),
    // Slice 6: a delegation revoked in the console ends here at the next poll.
    onDelegations: (present, fetchStartedAt) => {
      const ended = routineConsents?.reconcile(present, fetchStartedAt) ?? 0;
      if (ended) console.log(`perspicax directory: ${ended} routine delegation(s) ended in Perspicax`);
    },
    // Membership is the trigger of the Flow plugins: the first directory,
    // an invitation accepted, a declaration changed in Perspicax.
    onDirectory: () => {
      void orgFlowPlugins.sync("directory").catch(() => undefined);
      // lot 4: the organization's declarations, installed once here
      void syncOrgCapabilities("directory");
      void syncPersonalProviderDirectory();
    },
    version,
  });
  perspicaxDirectory.start(intervalMs);
  void syncPersonalProviderDirectory();
  // a newer Flow version: the sync fetches the marketplaces again when due
  setInterval(() => { void orgFlowPlugins.sync("schedule").catch(() => undefined); }, 30 * 60_000).unref();
  // at start: what is missing or older than the last directory read
  setTimeout(() => { void orgFlowPlugins.sync("start").catch(() => undefined); void syncOrgCapabilities("start"); }, 15_000).unref();
  // Slice 5: per-turn MCP tokens for the person who speaks.
  const directory = perspicaxDirectory;
  perspicaxMemory = new PerspicaxMemory({ link: () => directory });
  const issuer = IDENTITY.issuer;
  perspicaxMcp = new PerspicaxMcp({
    issuer,
    link: () => directory,
    // Routine runs and teammate turns: the same write twice at once is one.
    writeOnceScope: ({ threadId }) => activeRoutineRunForThread(threadId) || internalTurnThreads.has(threadId) ? "unattended" : null,
    // a live call keeps its Perspicax tools mounted from turn to turn
    keepWarm: (threadId) => Boolean(voiceCalls.active(threadId)),
    // 2026-10-28: a bot's own voice_call is a place_phone_call (its card,
    // the AI disclosure, the pilot and the do-not-call list)
    placeCall: (turn, args) => outbound.placeCall({
      principalId: vaultPrincipalForThread(turn.threadId), botId: turn.botId, threadId: turn.threadId, generation: turn.generation,
      room: Boolean(store.groupByThread(turn.threadId)),
    }, args),
    // 2026-10-26: a Perspicax server guard's GO (Flow: dry run, GO, read
    // back) is an approval card on the thread; Full access and Approve for
    // me never answer it, only the person (confirmHeldCard).
    askGo: ({ threadId, botId, message }) => confirmHeldCard({ threadId, botId, tool: "perspicax", summary: message }),
    // remote_support_open / status / close: the session shows in Sagax (server/remote-session-register.ts)
    onRemoteSupport: (call) => {
      const principalId = call.principalId || remoteSessionSpeaker(call.threadId);
      void remoteSessionRegistrar.observe({ ...call, ...(principalId ? { principalId } : {}) }).catch((error) => {
        console.warn(`remote session: the card could not be posted (${error instanceof Error ? error.name : "error"})`);
      });
    },
    // Direct MCP remote_support_open: Sagax fills host_id / nodekey / session
    // (model-supplied values are ignored or refused). Agents-catalog opens
    // already go through handleRemoteSupportCall; this covers the MCP bridge.
    openRemoteSupport: async (turn) => {
      const bot = store.bot(turn.botId);
      const person = isPrincipalId(turn.principalId) ? principals.byId(turn.principalId) : null;
      const ownerSub = person?.subject && person.subject.iss === issuer ? person.subject.sub : null;
      return guardRemoteSupportOpen({
        args: turn.args,
        botId: turn.botId,
        principalId: turn.principalId,
        ownerSub,
        remoteHosts: bot?.remoteHosts,
        ownsHost: async (hostId) => {
          const out = await remoteBotHosts.assertOwnHost(turn.principalId, hostId);
          return !("ok" in out && out.ok === false);
        },
        local: {
          dir: REMOTE_SUPPORT_DIR,
          technicianName: (personDisplayName(person) || cfg.profile?.name?.trim() || "").slice(0, 80),
          orgName: (process.env.SAGAX_ORG_NAME?.trim() || "Pulsatrix").slice(0, 80),
        },
        post: async (tool, toolArgs) => {
          const mcp = perspicaxMcp;
          if (!mcp) return { status: 409, body: { error: "Perspicax is not linked.", code: "profile_not_mounted" } };
          const answer = await mcp.callTool({
            threadId: turn.threadId,
            generation: turn.generation,
            botId: turn.botId,
            name: tool,
            args: toolArgs as never,
          });
          if (!answer.ok) {
            return {
              status: answer.code === "profile_not_mounted" ? 409 : 502,
              body: { error: answer.error, code: answer.code },
            };
          }
          const text = typeof answer.value === "string" ? answer.value : JSON.stringify(answer.value);
          return {
            status: 200,
            body: {
              text,
              isError: answer.isError,
              owner: { principalId: turn.principalId, botId: turn.botId },
            },
          };
        },
      });
    },
    subjectOf: (principalId) => {
      const person = isPrincipalId(principalId) ? principals.byId(principalId) : null;
      return person?.subject ? { iss: person.subject.iss, sub: person.subject.sub, disabled: person.disabledAt !== undefined } : null;
    },
    subjectToken: (subject) => manager.subjectToken(subject),
    // Slice 6: routine lineage speaks through the runAs's delegation.
    routineSubjectToken: (principalId) => routineConsents ? routineConsents.subjectToken(principalId) : Promise.resolve({ ok: false as const, error: "no_session" as const }),
    delegationRefused: (principalId) => routineConsents?.dropCache(principalId),
    botProfiles: (id) => store.bot(id)?.perspicax?.profiles,
    permissionGuard: ({ botId, principalId }) => {
      const person = isPrincipalId(principalId) ? principals.byId(principalId) : null;
      const env = mcpIdentityEnv({ botId, principalId, perspicaxRole: person?.perspicaxRole, teamIds: (person?.teams ?? []).map((team) => team.id), ...personOwnScope(principalId) });
      return {
        principal: principalFromEnv(env),
        owners: scopeOwnersFromEnv(env, principalId),
        // Perspicax authorizes its own tools: one Sagax does not list is
        // mcp:external, not an unknown tool (#1098)
        external: true,
        mode: permissionModeFromEnv(process.env),
        ownBotId: botId,
        deniedResources: deniedResourcesFromEnv(process.env),
        allowedSample: auditSampleFromEnv(process.env),
        audit: (record) => appendAdminAction(DATA_DIR, { ...mcpAuditRow(record, botId), actor: { kind: "loopback" } }),
      };
    },
    version,
  });
}

const oidcLogin = IDENTITY.kind === "perspicax" && oidcRp && idpSessions
  ? createOidcLoginRoutes({
    config: IDENTITY,
    rp: oidcRp,
    ...(accountReauth ? { reauth: accountReauth } : {}),
    ...(idpRevocations ? { revocations: idpRevocations } : {}),
    sessionCookie: SESSION_COOKIE,
    // A successful sign-in also refreshes the directory (fire and forget):
    // a person added in Perspicax a minute ago becomes pickable at once.
    forSubject: (input) => {
      if (input.teams?.length) orgTeams.mergeFromClaims(input.teams);
      const principal = principals.forSubject(input);
      void perspicaxDirectory?.refresh("sign-in");
      return principal;
    },
    issueSession: (input) => sessions.issue(input),
    // A back-channel logout also drops the person's cached owner keys (S4-14).
    grants: {
      unavailableReason: () => idpSessions.unavailableReason(),
      createGrant: (input) => idpSessions.createGrant(input),
      bindSession: (grantRef, sessionId) => idpSessions.bindSession(grantRef, sessionId),
      discard: (grantRef) => idpSessions.discard(grantRef),
      backchannelLogout: (input) => {
        perspicaxDirectory?.forgetSubject(input.sub);
        perspicaxMcp?.forgetSubject(input.iss, input.sub);
        // Slice 6: the delegation goes too; the person's routines pause.
        routineConsents?.endForSubject(input.iss, input.sub);
        return idpSessions.backchannelLogout(input);
      },
      createRoutineDelegation: (input) => {
        if (!routineConsents) throw new Error("routine delegations are unavailable");
        routineConsents.create(input);
      },
      sessionPrincipal: (sessionId) => sessions.byId(sessionId)?.principalId ?? null,
      // 2026-10-17: Perspicax erased the account (account purged event):
      // the same erasure as DELETE /api/me. A subject this server never knew
      // (or already erased and forgotten) is zeros.
      purgePerson: async ({ iss, sub }) => {
        const principal = principals.bySubject(iss, sub);
        if (!principal) return { bots: 0, threads: 0 };
        return deletePersonData(principal.id);
      },
      // 2026-10-08: the routine delegation comes with the sign-in.
      signedIn: ({ principalId, accessToken, accessExpiresAt }) => {
        void routineConsents?.keepAlive(principalId, accessToken ? { token: accessToken, ...(accessExpiresAt !== undefined ? { expiresAt: accessExpiresAt } : {}) } : undefined);
        // Pulsatrix Flow with this person's own token (installs what is
        // missing or older; silent when up to date).
        void orgFlowPlugins.sync("sign-in").catch(() => undefined);
      },
    },
    openPairing: (input) => sessions.openPairing(input),
    serverName: () => environmentDescriptor({ environmentId: ENVIRONMENT_ID, desktopManaged: DESKTOP_MANAGED }).label,
  })
  : null;

/** Slice 7: the bots as the console's Bots page reads them, with what a
 * manager's reach is checked against. Metadata only. */
function orgAdminBots(): Array<{ bot: AdminBot; reach: AdminBotReach }> {
  const profileNames = new Map((perspicaxDirectory?.profileCatalog() ?? []).map((profile) => [profile.id, profile.name] as const));
  const routineCounts = new Map<string, number>();
  for (const routine of routines?.listRoutines() ?? []) routineCounts.set(routine.botId, (routineCounts.get(routine.botId) ?? 0) + 1);
  return store.bots.map((bot) => {
    const facts = botFacts(bot);
    const engine = engineOfBot(bot);
    const plan = IDENTITY.kind === "perspicax"
      // A turn by someone other than the owner: what it would resolve to now.
      ? resolveEngineAccess(orgEngineInput(bot, { instanceId: engine.instanceId, driverKind: engine.driver }, { origin: "person", principalId: "" }))
      : { ok: true as const, via: "server" as const };
    const access: AccessKind = plan.ok ? plan.via : "none";
    const sectionName = sectionKey(bot.section);
    const record = sectionName && sectionChannels ? sectionChannels.byName(sectionName) : undefined;
    const shared = record && facts.sections?.length ? record : undefined;
    const lastActivity = store.tasks(bot.id).reduce<number | null>((latest, task) => {
      const at = typeof task.updatedAt === "number" ? task.updatedAt : null;
      return at !== null && (latest === null || at > latest) ? at : latest;
    }, null);
    const ownerRole = botOwnerOrgRole(bot) ?? "member";
    return {
      bot: {
        id: bot.id,
        name: bot.name,
        owner: adminPerson(facts.ownerPrincipalId),
        ownerRole,
        engine: { instanceId: engine.instanceId, driverKind: engine.driver, installed: engineInstalled(engine.instanceId) },
        model: bot.modelSelection?.model || null,
        access,
        mcpProfiles: (bot.perspicax?.profiles ?? []).map((id) => ({ id, name: profileNames.get(id) ?? id })),
        grants: wireGrants(facts.grants, describeGrantTarget).map((grant) => ({
          target: grant.target, kind: grant.kind, label: grant.label, level: grant.level, ...(grant.disabled ? { disabled: true as const } : {}),
        })),
        sections: shared ? [{ id: shared.id, name: shared.name, defaultLevel: shared.defaultLevel, members: shared.members.length }] : [],
        routines: routineCounts.get(bot.id) ?? 0,
        createdAt: typeof bot.createdAt === "number" ? bot.createdAt : null,
        lastActivityAt: lastActivity,
        status: bot.hidden ? "archived" : "active",
        label: sectionName || null,
        threads: botThreadIds(bot).length,
        look: botLook(bot, attachmentExists),
        persona: botPersona(bot),
        approvalMode: approvalModeFor(bot),
      },
      reach: orgBotReach(bot),
    };
  });
}

/** Every conversation of a bot: its main thread and each task. */
function botThreadIds(bot: BotRecord): string[] {
  return [...new Set([bot.threadId, ...store.tasks(bot.id).map((task) => task.threadId)])];
}

/** The organization's people, as the console's People page and Overview
 * count them: everyone of the directory who is not a service account. */
function orgConsolePeople(): Array<{ principalId: string; disabled: boolean }> {
  if (IDENTITY.kind !== "perspicax" || !perspicaxDirectory) return [];
  return orgDirectoryEntries(IDENTITY.issuer, perspicaxDirectory.people(), (iss, sub) => principals.bySubject(iss, sub))
    .filter((entry) => !entry.service && entry.principalId)
    .map((entry) => ({ principalId: entry.principalId!, disabled: Boolean(entry.disabled) }));
}

/** The console's Overview (server/org-admin-overview.ts). */
const orgOverviewDeps = {
  version: releaseVersion,
  startedAt: SERVER_STARTED_AT,
  deploy: () => deployFacts(),
  host: () => hostFacts(DATA_DIR),
  engines: () => selfCheckEngines(engineSelfCheck, engineSelfCheckAt, () => registry.entries().map((entry) => {
    const probe = engineProbes.get(entry.instanceId);
    return {
      id: entry.instanceId,
      name: engineDisplayName(entry.live ?? entry.shadow),
      installed: probe?.installed ?? engineInstalled(entry.instanceId),
      version: probe?.version ?? null,
    };
  })),
  sandboxes: async () => {
    if (!userSandbox) return { enabled: false, running: 0, limit: null };
    const people = orgConsolePeople().filter((person) => !person.disabled).map((person) => person.principalId);
    return { enabled: true, ...(await userSandbox.overview(people)) };
  },
  presence: () => orgConsolePeople().filter((person) => !person.disabled).map((person) => ({
    principalId: person.principalId,
    state: publicPresence(presence.view(person.principalId), presenceHiddenFor(person.principalId)).state,
  })),
  usageRows: (range: { from: Date; to: Date }) => readUsage(DATA_DIR, range),
  routineRuns: (from: number) => (routines?.listRuns(from) ?? []).map((run) => {
    const bot = store.bot(run.botId);
    return {
      routineId: run.routineId, botId: run.botId, status: run.status, at: run.startedAt ?? run.scheduledFor ?? run.createdAt,
      ownerPrincipalId: bot ? effectiveBotOwner(bot) || null : null, runAsPrincipalId: run.runAs ?? null,
    };
  }),
  problems: (from: number) => readProblems(DATA_DIR, { from }),
  backup: () => readBackupStatus(process.env.SAGAX_BACKUP_STATUS_FILE?.trim() || join(DATA_DIR, "backup-status.json")),
};

/** What a person's own turns run with on each engine (the order of
 * engine-credentials.ts), as /api/me/engines words it. */
function personEngineAccess(principalId: string): Array<{ id: string; via: EngineVia; signedIn: boolean; key: boolean }> {
  const person = principals.byId(principalId);
  const sub = IDENTITY.kind === "perspicax" && person?.subject?.iss === IDENTITY.issuer ? person.subject.sub : undefined;
  const held = sub ? perspicaxDirectory?.providerKeys(sub) ?? [] : [];
  return registry.entries().map((entry) => {
    const driver = entry.shadow?.driverKind ?? entry.live?.driverKind ?? "";
    // #1533: an API-key engine never runs on a subscription
    const signedIn = Boolean(engineLogins && isLoginDriver(driver) && !keyOnlyInstance(entry.instanceId) && engineLogins.signedIn(principalId, driver));
    const key = providersOfInstance(entry.instanceId, driver).some((provider) => held.includes(provider));
    const orgKey = driverKeyBacked(cfg, driver, entry.instanceId);
    const off = !engineInstalled(entry.instanceId) || person?.disabledAt !== undefined || Boolean(person?.consoleDisabled);
    const via: EngineVia = off ? "none" : signedIn ? "subscription" : key ? "key" : orgKey ? "org-key" : "none";
    return { id: entry.instanceId, via, signedIn, key };
  });
}

/** The console's People (server/org-admin-people.ts). */
const orgPeopleDeps: PeopleDeps = {
  permissions: (principalId) => {
    const effective = principalPermissions(principalId);
    return { source: effective.source, effective: permissionList(effective), narrowedBy: [...effective.narrowedBy] };
  },
  people: () => {
    if (IDENTITY.kind !== "perspicax" || !perspicaxDirectory) return [];
    return orgDirectoryEntries(IDENTITY.issuer, perspicaxDirectory.people(), (iss, sub) => principals.bySubject(iss, sub))
      .filter((entry) => !entry.service)
      .map((entry) => {
        const person = principals.byId(entry.principalId);
        const view = publicPresence(presence.view(entry.principalId), presenceHiddenFor(entry.principalId));
        return {
          principalId: entry.principalId,
          sub: person?.subject?.sub ?? null,
          name: entry.name,
          role: entry.role,
          perspicaxDisabled: entry.disabled || person?.disabledAt !== undefined,
          consoleDisabled: person?.consoleDisabled ?? null,
          presence: { state: view.state, lastSeenAt: view.lastSeenAt },
          engines: personEngineAccess(entry.principalId).map(({ id, via }) => ({ id, via })),
        };
      });
  },
  person: adminPerson,
  bots: () => orgAdminBots(),
  routines: () => (routines?.listRoutines() ?? []).map((routine) => ({ id: routine.id, name: routine.name, botId: routine.botId, runAs: effectiveRunAs(routine) ?? null, enabled: routine.enabled })),
  // 2026-10-11: pause or resume every routine that runs as a person
  setRoutineEnabled: (routineId, enabled) => {
    try {
      return Boolean(routines?.update(routineId, { enabled }));
    } catch {
      return false;
    }
  },
  usageRows: (range) => readUsage(DATA_DIR, range),
  shared: (principalId) => {
    const teams = new Set((principals.byId(principalId)?.teams ?? []).map((team) => team.id));
    return store.bots.flatMap((bot): Array<{ botId: string; botName: string; level: string; via: "user" | "team" | "section" }> => {
      const facts = botFacts(bot);
      if (facts.ownerPrincipalId === principalId) return [];
      const direct = facts.grants.find((grant) => grant.target === `user:${principalId}`);
      if (direct) return [{ botId: bot.id, botName: bot.name, level: direct.level, via: "user" as const }];
      const team = facts.grants.find((grant) => grant.target.startsWith("team:") && teams.has(grant.target.slice(5)));
      if (team) return [{ botId: bot.id, botName: bot.name, level: team.level, via: "team" as const }];
      const sectionName = sectionKey(bot.section);
      const record = sectionName && sectionChannels ? sectionChannels.byName(sectionName) : undefined;
      const member = record?.members.find((entry) => entry.target === `user:${principalId}` || (entry.target.startsWith("team:") && teams.has(entry.target.slice(5))));
      return record && member ? [{ botId: bot.id, botName: bot.name, level: record.defaultLevel, via: "section" as const }] : [];
    });
  },
  connections: (principalId) => {
    return {
      engines: personEngineAccess(principalId),
      mcpServers: Object.entries(personConnections.servers(principalId)).sort(([a], [b]) => a.localeCompare(b)).map(([name, server]) => ({
        id: name, name, transport: server.kind === "stdio" ? "stdio" as const : "remote" as const,
        state: server.enabled ? "enabled" as const : "disabled" as const,
      })),
    };
  },
  setDisabled: (principalId, value) => {
    principals.setConsoleDisabled(principalId, value);
    if (value) {
      for (const sessionId of sessions.revokeWhere((session) => session.principalId === principalId)) engineLogins?.revokeOwner(sessionId);
      audienceChanged();
    }
  },
  resetAccess: async (principalId, scope) => {
    const engineLoginsCleared = scope === "sessions" ? 0 : engineLogins?.clearAll(principalId) ?? 0;
    const revoked = scope === "engine-logins" ? [] : sessions.revokeWhere((session) => session.principalId === principalId);
    for (const sessionId of revoked) engineLogins?.revokeOwner(sessionId);
    return { engineLogins: engineLoginsCleared, sessions: revoked.length };
  },
  revokeConnections: (principalId, body) => revokeOrgConnections(orgPersonConnectionDeps, principalId, body),
  connectionListing: (principalId) => orgConnectionListing({
    principalId, github: githubConnect.status(principalId, personGithub(principalId)),
    servers: personConnections.servers(principalId), lastUsed: (name) => stdioRelay.lastUsed(principalId, name), plugins: orgPersonConnectionDeps.plugins(principalId),
  }),
};

/** A person who may own a bot on this server: known, of this
 * organization, not disabled (either way). */
function consoleOwner(principalId: string): AdminPerson | null {
  const person = principals.byId(principalId);
  if (!person || person.disabledAt !== undefined || person.consoleDisabled || person.mergedInto) return null;
  if (IDENTITY.kind === "perspicax" && person.subject?.iss !== IDENTITY.issuer) return null;
  return adminPerson(person.id);
}

/** One bot as a package document v2 (the Share dialog's format): the bot
 * alone, every skill that fits, no memory; `routines` decides whether its
 * routines ride along (they arrive off on import). */
function singleBotPackage(bot: BotRecord, withRoutines: boolean) {
  const team = sectionKey(bot.section);
  const exportable = { ...bot, hidden: false } as BotRecord;
  const skills = collectTeamSkills([exportable], "all");
  if (!skills.ok) throw new ConsoleRefusal(409, "skills_unreadable", skills.error);
  try {
    return createTeamPackageExport({
      team,
      name: bot.name,
      authorName: cfg.profile?.name?.trim(),
      bots: [exportable],
      groups: [],
      routines: withRoutines ? (routines?.listRoutines() ?? []).filter((routine) => routine.botId === bot.id) : [],
      published: null,
      skillsByBot: skills.skillsByBot,
      skillSelection: "all",
      mcpServers: cfg.mcpServers ?? {},
      skipped: skills.skipped,
      preset: null,
    });
  } catch (error) {
    if (error instanceof TeamExportError) throw new ConsoleRefusal(error.status, "export_refused", error.message);
    throw error;
  }
}

/** Import a package document for `ownerPrincipalId` (the console's Import
 * and Clone): every bot it creates is theirs. */
async function importPackageFor(raw: unknown, ownerPrincipalId: string): Promise<{ bots: BotRecord[]; warnings: string[] }> {
  let document: PackageDocument;
  try {
    if (!isBotPackage(raw)) throw new Error("This is not a Sagax bot package.");
    document = parsePackageDocument(raw, { trust: "file" });
  } catch (error) {
    throw new ConsoleRefusal(400, "invalid_package", error instanceof Error ? error.message.slice(0, 300) : "Invalid bot package.");
  }
  let result: PackageImportResult;
  try {
    const imported = importPackageDocument(document, { mode: "add", cwd: null, trust: "file" }, packageImportDeps(await defaultSelection()));
    if (imported.alreadyAdded) throw new ConsoleRefusal(409, "already_added", "This package was already added.");
    result = imported;
  } catch (error) {
    if (error instanceof PackageImportError) throw new ConsoleRefusal(error.status, error.code ?? "import_refused", error.message);
    throw error;
  }
  for (const bot of result.bots) store.patchBot(bot.id, { ownerUserId: ownerPrincipalId });
  botMailResync();
  settleMemberAutoLevels(result.bots.map((bot) => bot.id));
  for (const bot of result.bots) {
    const current = store.bot(bot.id);
    if (current) broadcast({ kind: "bot", bot: publicBot(current) });
  }
  return { bots: result.bots, warnings: result.skipped.map((skip) => `${skip.part}: ${skip.reason}`) };
}

/** The console's Bots (server/org-admin-bots.ts). */
/** 2026-10-16, the console's "Approve for me" bulk action (POST
 * /api/org/admin/bots/bulk, action approvalMode): the bot's default level
 * to Ask or Approve for me, as the bot PATCH sets it. Never Full, Custom or
 * Edits from here. A bot on Full or Custom is left alone (those need the
 * owner's own confirmation to leave, as everywhere). With `threads`, its
 * conversations stored on Ask follow to Auto; a conversation on any other
 * level keeps it (never lowered). The caller audits the change. */
function setBotApprovalModeFromConsole(botId: string, mode: "ask" | "auto", threads: boolean): { before: string; after: string; threadsMoved: string[] } {
  const bot = store.bot(botId);
  if (!bot) throw new ConsoleRefusal(404, "not_found", "No such bot.");
  const before = approvalModeFor(bot);
  if (before === "full" || before === "custom") {
    throw new ConsoleRefusal(409, "elevated_level", `This bot is on ${before === "full" ? "Full access" : "Custom"}: only its owner can change that level.`);
  }
  if (!supportsApprovalMode(bot.modelSelection, mode)) {
    throw new ConsoleRefusal(400, "mode_not_supported", `This bot's engine has no ${mode === "auto" ? "Approve for me" : "Ask"} mode.`);
  }
  if (bot.approvalGrant) throw new ConsoleRefusal(409, "busy", "The bot's approval level is still being confirmed.");
  const tasks = threads && mode === "auto" ? store.tasks(bot.id) : [];
  // 2026-10-17 (re-review of #688): an admin's console never saves an
  // automatic level on a member's bot, or its threads, while the
  // organization turned them off; refused, never stored.
  if (memberAutoRefused(bot, [before, ...tasks.map((task) => task.approvalMode)], mode)) {
    throw new ConsoleRefusal(403, MEMBER_AUTO_NOT_ALLOWED.code, MEMBER_AUTO_NOT_ALLOWED.error);
  }
  if (bot.busy || threadBusy(bot.id, bot.threadId) || tasks.some((task) => threadBusy(bot.id, task.threadId))) {
    throw new ConsoleRefusal(409, "busy", "The bot is working: try again when its turn ends.");
  }
  if (before !== mode) store.patchBot(bot.id, { approvalMode: mode, autoApprove: mode === "auto" });
  const threadsMoved: string[] = [];
  for (const task of tasks) {
    if (task.threadId === bot.threadId || task.approvalMode !== "ask") continue;
    if (!supportsApprovalMode(task.modelSelection ?? bot.modelSelection, "auto")) continue;
    store.patchTask(bot.id, task.threadId, { approvalMode: "auto", autoApprove: true });
    threadsMoved.push(task.threadId);
  }
  const updated = store.bot(bot.id);
  if (updated && (before !== mode || threadsMoved.length)) broadcast({ kind: "bot", bot: wireBot(updated) });
  return { before, after: updated ? approvalModeFor(updated) : mode, threadsMoved };
}

const orgBotsDeps: BotsDeps = {
  bots: () => orgAdminBots(),
  capabilities: (botId, viewer) => consoleBotCapabilities(botId, viewer),
  avatar: (botId) => {
    const bot = store.bot(botId);
    return bot ? readBotAvatar(bot, ATTACHMENTS_DIR) : null;
  },
  detail: (botId) => {
    const bot = store.bot(botId);
    if (!bot) return null;
    const threads = botThreadIds(bot);
    const lastAt = store.tasks(bot.id).reduce<number | null>((latest, task) => typeof task.updatedAt === "number" && (latest === null || task.updatedAt > latest) ? task.updatedAt : latest, null);
    const mode = approvalModeFor(bot);
    return {
      threads: { count: threads.length, lastAt },
      soul: { chars: (bot.soul ?? "").length, summary: instructionsLead(bot.soul) ?? null },
      skills: listBotSkills(bot).map((skill) => ({ id: skill.name, name: skill.name, source: skill.source || null })),
      permissions: { approvalMode: mode, fullAccess: mode === "full" },
      routineList: (routines?.listRoutines() ?? []).filter((routine) => routine.botId === bot.id)
        .map((routine) => ({ id: routine.id, name: routine.name, enabled: routine.enabled, schedule: routineScheduleLabel(routine.schedule) })),
    };
  },
  owner: consoleOwner,
  ownerBySub: (sub) => {
    if (IDENTITY.kind !== "perspicax") return null;
    const person = principals.bySubject(IDENTITY.issuer, sub);
    return person ? consoleOwner(person.id) : null;
  },
  clone: async (botId, input) => {
    const source = store.bot(botId);
    if (!source) throw new ConsoleRefusal(404, "not_found", "No such bot.");
    const exported = singleBotPackage(source, false);
    const { bots } = await importPackageFor(exported.document, input.ownerPrincipalId);
    const copy = bots[0];
    if (!copy) throw new ConsoleRefusal(500, "clone_failed", "The copy could not be made.");
    // The source's model and settings; a copy starts with no grants, no
    // memory, no threads and no routines, and never with full access.
    // a member's copy never starts on an automatic level the organization
    // refuses for members' bots (member-auto-approval.ts)
    const sourceMode = approvalModeFor(source);
    const mode = memberAutoRefused(copy, ["ask"], sourceMode) ? "ask" : sourceMode;
    store.patchBot(copy.id, {
      modelSelection: structuredClone(source.modelSelection),
      ...(input.name ? { name: input.name } : {}),
      ...(mode !== "full" && mode !== "custom" ? { approvalMode: mode, autoApprove: mode === sourceMode ? source.autoApprove : false } : {}),
      ...(source.speakReplies !== undefined ? { speakReplies: source.speakReplies } : {}),
      ...(source.voice !== undefined ? { voice: source.voice } : {}),
      ...(source.voiceNotes !== undefined ? { voiceNotes: source.voiceNotes } : {}),
      ...(source.memoryEnabled !== undefined ? { memoryEnabled: source.memoryEnabled } : {}),
      ...(source.loopGuard !== undefined ? { loopGuard: source.loopGuard } : {}),
      ...(storedTeamMemorySharing(source) ? { teamMemorySharing: "private" as const } : {}),
      ...(source.memoryUpkeep !== undefined ? { memoryUpkeep: source.memoryUpkeep } : {}),
      ...(source.browser !== undefined ? { browser: source.browser } : {}),
      ...(source.computer !== undefined ? { computer: source.computer } : {}),
      ...(source.toolScope !== undefined ? { toolScope: structuredClone(source.toolScope) } : {}),
      ...(source.mcpServers ? { mcpServers: [...source.mcpServers] } : {}),
      ...(source.assignedSkills ? { assignedSkills: [...source.assignedSkills] } : {}),
      ...(source.avatarUrl ? { avatarUrl: source.avatarUrl, ...(source.avatarCrop ? { avatarCrop: source.avatarCrop } : {}) } : {}),
    });
    // The source's skills were on: so are the copy's.
    for (const skill of listSkills(source.id)) if (skill.enabled) setSkillEnabled(copy.id, skill.name, true);
    const current = store.bot(copy.id);
    if (current) broadcast({ kind: "bot", bot: publicBot(current) });
    return copy.id;
  },
  setArchived: (botId, archived) => {
    const bot = store.bot(botId);
    if (!bot) throw new ConsoleRefusal(404, "not_found", "No such bot.");
    if (archived && bot.chiefOfStaff) throw new ConsoleRefusal(409, "primary_bot", "This is its owner's Primary Bot: they choose another one before it can be archived.");
    store.patchBot(botId, { hidden: archived });
  },
  transfer: (botId, ownerPrincipalId) => {
    const bot = store.bot(botId);
    if (!bot) throw new ConsoleRefusal(404, "not_found", "No such bot.");
    const facts = botFacts(bot);
    const previous = facts.ownerPrincipalId;
    // Grants kept; the old owner keeps the bot at `manage`; a grant to the
    // new owner becomes ownership. A Primary Bot is its owner's own: it
    // stops being one.
    const grants = facts.grants.filter((grant) => grant.target !== `user:${ownerPrincipalId}` && grant.target !== `user:${previous}`);
    if (previous) grants.push({ target: `user:${previous}`, level: "manage", by: previous, at: Date.now() } as (typeof grants)[number]);
    if (bot.chiefOfStaff) store.clearPrimaryBot(botId);
    store.patchBot(botId, { ownerUserId: ownerPrincipalId });
    // its memory and the threads that follow its owner (no person of their
    // own) take the new owner's key now, whole (docs/content-encryption.md):
    // the previous owner's erasure never takes them
    const following = store.tasks(botId).filter((task) => !task.ownerPrincipalId).map((task) => task.threadId);
    contentOwnerChanged(following, [botId]);
    botMailResync();
    store.setBotGrants(botId, grants);
    settleMemberAutoLevels([botId]);
    audienceChanged();
  },
  setModel: (botId, input) => {
    const bot = store.bot(botId);
    if (!bot) throw new ConsoleRefusal(404, "not_found", "No such bot.");
    const instanceId = input.engineInstanceId ?? bot.modelSelection.instanceId;
    const entry = registry.entries().find((candidate) => candidate.instanceId === instanceId);
    if (!entry || !engineInstalled(instanceId)) throw new ConsoleRefusal(400, "engine_not_installed", `The engine ${instanceId} is not installed on this server.`);
    if (!consoleEngineAllowed(instanceId)) throw new ConsoleRefusal(400, "engine_not_allowed", `The organization's policy does not allow the engine ${instanceId}.`);
    if (bot.approvalGrant) throw new ConsoleRefusal(409, "busy", "Wait for the approval-level change to finish before changing models.");
    // null: the bot's model on the same engine, else the engine's default.
    const model = input.model ?? (instanceId === bot.modelSelection.instanceId ? bot.modelSelection.model : registry.get(instanceId)?.models.default ?? null);
    if (!model) throw new ConsoleRefusal(400, "bad_request", "This engine has no default model: choose one.");
    const checked = checkedModelSelection({ instanceId, model }, { selection: bot.modelSelection, busy: threadBusy(bot.id, bot.threadId) }, true);
    if (!checked.ok) throw new ConsoleRefusal(checked.status, checked.status === 409 ? "busy" : "bad_request", checked.error);
    store.patchBot(bot.id, { modelSelection: checked.selection });
  },
  setApprovalMode: (botId, mode, threads) => setBotApprovalModeFromConsole(botId, mode, threads),
  stop: forceStopBot,
  remove: (botId) => deleteBotWithLifecycle(botId),
  notifyOwner: (botId, action, adminPrincipalId) => {
    const bot = store.bot(botId);
    const owner = bot ? botFacts(bot).ownerPrincipalId : undefined;
    if (!owner) return;
    const admin = principals.byId(adminPrincipalId);
    const who = admin ? personDisplayName(admin) || "An admin" : "An admin";
    notify({
      kind: "admin-action", botId, botName: bot?.name ?? "", threadId: bot?.threadId ?? "",
      title: action === "stop" ? `${bot?.name} was stopped by an admin` : `${bot?.name} was deleted by an admin`,
      body: action === "stop" ? `${who} stopped all of its work.` : `${who} deleted this bot.`,
      audience: [owner],
    });
  },
  exportPackage: (botId) => {
    const bot = store.bot(botId);
    if (!bot) throw new ConsoleRefusal(404, "not_found", "No such bot.");
    const exported = singleBotPackage(bot, true);
    return { document: exported.document, filename: exported.filename, redacted: exported.redacted, skipped: exported.skipped };
  },
  // The canonical bot zip (server/bot-zip.ts), for "Copy to another server".
  exportZip: (botId, options) => {
    const plan = planBotZip(botZipHost, botId, options);
    return { filename: plan.filename, bytes: plan.bytes, write: (sink) => writeBotZip(plan, sink) };
  },
  importZip: async (request, input) => {
    const file = join(DATA_DIR, "tmp", "bot-imports", `console-${randomUUID()}.upload`);
    try {
      await stageBotZipUpload(request, file);
      const inspected = inspectBotZip(file);
      try {
        if (input.preview) return { preview: await previewBotZip(botZipHost, inspected, { asMember: false }, input.name) };
        const result = await importBotZip(botZipHost, inspected, { ownerPrincipalId: input.ownerPrincipalId, asMember: false, conversations: input.conversations, sharing: input.sharing, ...(input.name ? { name: input.name } : {}) });
        const bot = store.bot(result.botId);
        if (bot) broadcast({ kind: "bot", bot: publicBot(bot) });
        return { botId: result.botId, warnings: result.warnings };
      } finally {
        closeInspected(inspected);
      }
    } catch (error) {
      if (error instanceof BotZipError) throw new ConsoleRefusal(error.status, error.code, error.message);
      throw error;
    } finally {
      rmSync(file, { force: true });
    }
  },
  importPackage: async (document, input) => {
    const { bots, warnings } = await importPackageFor(document, input.ownerPrincipalId);
    const first = bots[0];
    if (!first) throw new ConsoleRefusal(400, "invalid_package", "The package has no bot.");
    if (input.name) store.patchBot(first.id, { name: input.name });
    return { botId: first.id, warnings };
  },
};

/** The organisation bot catalogue, Browse Bots (server/routes/bot-catalog.ts).
 * Import reuses the console's clone, for the viewer. */
const CATALOG_MEMORY_MAX = 200;
ROUTES.push(createBotCatalogRoutes({
  organization: () => IDENTITY.kind === "perspicax",
  bots: () => store.bots.map((bot) => ({
    id: bot.id,
    name: bot.name,
    title: bot.title ?? "",
    description: bot.description ?? "",
    look: {
      color: bot.color,
      ...(bot.mascotExpression !== undefined ? { mascotExpression: bot.mascotExpression } : {}),
      ...(bot.mascotBody !== undefined ? { mascotBody: bot.mascotBody } : {}),
      ...(bot.mascotSkin !== undefined ? { mascotSkin: bot.mascotSkin } : {}),
      ...(bot.mascotLook !== undefined ? { mascotLook: bot.mascotLook } : {}),
      avatarUrl: bot.avatarUrl ?? null,
      ...(bot.avatarCrop ? { avatarCrop: bot.avatarCrop } : {}),
    },
    ownerPrincipalId: effectiveBotOwner(bot),
    archived: bot.hidden === true,
    primary: bot.chiefOfStaff === true,
    ...(bot.catalog?.published ? { catalog: bot.catalog } : {}),
  })),
  viewer: (auth) => {
    const principalId = actorPrincipalId(auth);
    if (!principalId) return null;
    return { principalId, admin: orgAdminCaller(auth), canCreate: botCreationAllowed(auth), botsReadOnly: callerBotsReadOnly(auth), feature: callerCan(auth, "bots.catalogFeature") };
  },
  level: (auth, botId) => {
    const bot = store.bot(botId);
    if (!bot) return null;
    // The operator at this computer holds every bot; the catalogue still
    // calls "mine" only the bots they own on an organization server.
    if (IDENTITY.kind === "perspicax" && !authzViewerFor(auth)) return effectiveBotOwner(bot) === actorPrincipalId(auth) ? "owner" : null;
    return viewerBotLevel(auth, bot);
  },
  personName: (principalId) => adminPerson(principalId).name,
  detail: (botId, options) => {
    const bot = store.bot(botId);
    if (!bot) return null;
    let memories: string[] | null = null;
    if (options.memories) {
      memories = [];
      if (bot.memoryEnabled !== false) {
        const today = new Date().toISOString().slice(0, 10);
        try {
          memories = parseMemoryEntries(readMemoryDoc(bot.id, MEMORY_INDEX).text)
            .filter((entry) => !entry.struck && !memoryEntryExpired(entry, today) && entry.body)
            .map((entry) => entry.body)
            .slice(0, CATALOG_MEMORY_MAX);
        } catch {
          memories = [];
        }
      }
    }
    return {
      soul: bot.soul ?? "",
      memories,
      skills: listBotSkills(bot).filter((skill) => skill.enabled).map((skill) => ({ name: skill.name, description: skill.description ?? "" })),
      routines: (routines?.listRoutines() ?? []).filter((routine) => routine.botId === bot.id)
        .map((routine) => ({ name: routine.name, schedule: routine.schedule, enabled: routine.enabled })),
      integrations: [
        ...(bot.mcpServers ?? []).map((name) => ({ name, kind: "mcp" as const })),
        ...(bot.browser ? [{ name: "browser", kind: "browser" as const }] : []),
      ],
    };
  },
  setListing: (botId, listing) => {
    const bot = store.bot(botId);
    if (!bot) return;
    store.patchBot(botId, { catalog: listing ?? undefined });
    const current = store.bot(botId);
    if (current) broadcast({ kind: "bot", bot: publicBot(current) });
  },
  clone: async (botId, input) => {
    const id = await orgBotsDeps.clone(botId, { ownerPrincipalId: input.ownerPrincipalId, ...(input.name ? { name: input.name } : {}) });
    const source = store.bot(botId);
    // The Perspicax profile list travels with the copy; a member's copy
    // also goes back to a member's defaults for where it runs and what it
    // reaches on the host (an admin's keeps the source's settings).
    store.patchBot(id, {
      ...(source?.perspicax ? { perspicax: structuredClone(source.perspicax) } : {}),
      // 2026-10-26: a copy of the person's own bot keeps its remote
      // MCP servers; a stdio one runs on the organization's server
      ...(input.asMember ? memberImportReset(input.ownSource ? {
        mcpServers: source?.mcpServers ?? [],
        remote: (name) => {
          const parsed = parseStoredMcpServer(name, cfg.mcpServers?.[name]);
          return parsed.ok && isRemoteMcpServer(parsed.server);
        },
      } : undefined) : {}),
    });
    const current = store.bot(id);
    if (current) broadcast({ kind: "bot", bot: publicBot(current) });
    return id;
  },
  audit: (auth, row) => {
    appendAdminAction(DATA_DIR, {
      category: "bot",
      ...row,
      actor: IDENTITY.kind === "perspicax" ? orgAuditActor(auth) : decisionActorFor(auth),
    });
  },
}));

/** A bot as one zip (server/bot-zip.ts, server/routes/bot-zip.ts): the
 * persona editor's Export and Import, New bot, Browse Bots > Templates and
 * the admin console all read and write this one format. */
function mcpServerSummary(name: string): { transport?: string; url?: string; command?: string; valueNames: string[] } | undefined {
  const raw = (cfg.mcpServers ?? {})[name];
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
  const spec = raw as Record<string, unknown>;
  const names = (value: unknown) => value && typeof value === "object" && !Array.isArray(value) ? Object.keys(value).slice(0, 50) : [];
  let url: string | undefined;
  if (typeof spec.url === "string") {
    try {
      const parsed = new URL(spec.url);
      url = `${parsed.origin}${parsed.pathname}`;
    } catch { url = undefined; }
  }
  return {
    ...(typeof spec.type === "string" ? { transport: spec.type.slice(0, 20) } : url ? { transport: "http" } : typeof spec.command === "string" ? { transport: "stdio" } : {}),
    ...(url ? { url } : {}),
    ...(typeof spec.command === "string" ? { command: spec.command.split(/[\\/]/).pop()!.slice(0, 200) } : {}),
    valueNames: [...names(spec.headers), ...names(spec.env)],
  };
}
const botZipHost: BotZipHost = {
  store,
  dataDir: DATA_DIR,
  get appVersion() { return serverVersion(); },
  get organization() { return IDENTITY.kind === "perspicax"; },
  routines: () => routines,
  webhooks: () => ({
    list: () => webhooks.list(),
    create: (input) => webhooks.create(input as Parameters<typeof webhooks.create>[0]),
    remove: (id) => webhooks.remove(id),
  }),
  plugins: botPlugins,
  marketplaceTokenSources: (botId) => marketplaceCredentials.sourcesFor(botId),
  emailOf: (principalId) => principals.byId(principalId)?.email ?? undefined,
  principalByEmail: (email) => principals.byEmail(email)?.id ?? undefined,
  mcpServer: mcpServerSummary,
  engineUsable: (selection) => Boolean(registry.get(selection.instanceId)) && engineInstalled(selection.instanceId)
    && consoleEngineAllowed(selection.instanceId) && (!hostedModels || hostedModels.allows(selection)),
  defaultSelection: () => defaultSelection(),
  sectionExists: (name) => store.sections.includes(name),
  creationRefusal: () => store.bots.length >= MAX_WORKSPACE_BOTS ? `This workspace is limited to ${MAX_WORKSPACE_BOTS} bots.` : null,
  browserProfileExists: (id) => id === "guest" || (cfg.browserProfiles ?? []).some((profile) => profile.id === id),
  lookRefusal: (principalId, look) => {
    if (!principalId) return null;
    try {
      return lockedLookChange(undefined, look, new Set(achievementStore.snapshot(principalId).rewards))?.error ?? null;
    } catch {
      return null;
    }
  },
  cwdUsable: (path) => validateBotCwd(path).ok,
  importLegacy: async (document, owner, name) => {
    const { bots, warnings } = await importPackageFor(document, owner);
    const first = bots[0];
    if (!first) throw new ConsoleRefusal(400, "invalid_package", "The package has no bot.");
    if (name) store.patchBot(first.id, { name });
    return { botId: first.id, warnings };
  },
};
ROUTES.push(createBotZipRoutes({
  host: botZipHost,
  stagingDir: join(DATA_DIR, "tmp", "bot-imports"),
  mayExport: (auth, botId) => {
    const bot = store.bot(botId);
    if (!bot) return false;
    const level = viewerBotLevel(auth, bot);
    return level === "owner" || level === "manage" || orgAdminCaller(auth);
  },
  importer: (auth) => {
    const principalId = creatingBotOwnerId(auth);
    if (auth.kind === "session" && !principalId) return null;
    return {
      principalId: principalId || undefined,
      key: principalId || "local",
      canCreate: botCreationAllowed(auth) && !callerBotsReadOnly(auth),
      asMember: IDENTITY.kind === "perspicax" && !orgAdminCaller(auth),
    };
  },
  audit: (auth, row) => {
    appendAdminAction(DATA_DIR, {
      category: "bot",
      ...row,
      actor: IDENTITY.kind === "perspicax" ? orgAuditActor(auth) : decisionActorFor(auth),
    });
  },
  imported: (botId) => {
    const bot = store.bot(botId);
    if (bot) broadcast({ kind: "bot", bot: publicBot(bot) });
  },
  wireBot: (botId) => {
    const bot = store.bot(botId);
    return bot ? publicBot(bot) : undefined;
  },
  xaiMarketplaceBot: async (slug) => (await xaiMarketplace.bot(slug)).bot,
}));

/** The console's Routines and Approvals (server/org-admin-routines.ts). */
const orgRoutinesDeps: RoutinesDeps = {
  routines: () => routines?.listRoutines() ?? [],
  runs: (from) => routines?.listRuns(from) ?? [],
  bot: (botId) => {
    const bot = store.bot(botId);
    return bot ? { id: bot.id, name: bot.name, ownerPrincipalId: effectiveBotOwner(bot) } : null;
  },
  runAs: (routine) => effectiveRunAs(routine) ?? null,
  person: adminPerson,
  scheduleLabel: (routine) => routineScheduleLabel(routine.schedule),
  usageRows: (range) => readUsage(DATA_DIR, range),
  inFlight: routineRunInFlight,
  runNow: (routineId) => routines?.runNow(routineId) ?? null,
  // No writer meta: an admin pausing a routine does not make it run as them.
  setEnabled: (routineId, enabled) => routines?.update(routineId, { enabled }) ?? null,
  orgApprovals: (viewer) => pendingApprovalsFor(viewer, "org"),
  decisions: (range) => readDecisionRange(DATA_DIR, range),
  decisionPerson: (actor) => {
    if (!actor) return null;
    if (actor.kind === "loopback") return { principalId: "", sub: null, name: "This computer" };
    if (actor.kind === "worker") return { principalId: "", sub: null, name: "A local worker" };
    if (actor.userId && isPrincipalId(actor.userId) && principals.byId(actor.userId)) return adminPerson(actor.userId);
    return { principalId: "", sub: null, name: actor.label.includes("@") ? "Signed-in user" : actor.label };
  },
};

/** The console's routines calendar (server/org-admin-runs.ts): every run
 * in a window, past and planned, with the Automations scope rules. */
const orgRoutineRunsDeps: RoutineRunsDeps = {
  routines: () => routines?.listRoutines() ?? [],
  runs: (from, to) => routines?.listRuns(from, to) ?? [],
  bot: orgRoutinesDeps.bot,
  runAs: (value) => effectiveRunAs(value) ?? null,
  person: adminPerson,
  teams: (value) => routineScopeFacts(value).teamIds.slice(),
  permissions: (principalId) => {
    const effective = principalPermissions(principalId);
    return { viewTeam: can(effective, "routines.viewTeam"), viewAll: can(effective, "routines.viewAll") };
  },
  next: (schedule, after) => nextOccurrence(schedule, after),
};

/** The console's Computers (server/org-admin-computers.ts): every
 * person's server environment, and every connected desktop, read only. */
const orgComputersDeps: ComputersDeps = {
  people: () => orgConsolePeople(),
  person: adminPerson,
  environments: userSandbox ? {
    provisioner: () => userSandbox.provisioner(),
    inventory: (principalIds, timeoutMs) => userSandbox.inventory(principalIds, timeoutMs),
    power: (principalId, action) => userSandbox.power(principalId, action),
    update: (principalId) => userSandbox.update(principalId),
    reset: (principalId) => userSandbox.reset(principalId),
    remove: (principalId) => userSandbox.removeNow(principalId),
  } : null,
  turnRunning: userSandboxTurnRunning,
  desktops: () => IDENTITY.kind !== "perspicax" ? [] : desktopBridges.inventory().flatMap((desktop) => {
    const person = principals.byId(desktop.person);
    return person ? [{ principalId: person.id, desktopId: desktop.id, name: desktop.name, platform: desktop.platform, online: desktop.online, lastSeenAt: desktop.lastSeenAt, localVm: desktop.localVm, version: desktop.version }] : [];
  }),
  bots: () => store.bots.map((bot) => ({ id: bot.id, name: bot.name, ownerPrincipalId: effectiveBotOwner(bot), computer: bot.computer ?? null })),
  activity: ({ computerId, principalId, kind, limit }) => {
    // The console's own actions on it, and the bots' switches to and from
    // it on behalf of its person (`computer.switch`, Auto's computer).
    const surfaces = kind === "server-environment" ? ["cloud"] : ["this_computer", "local_vm"];
    const own = readOrgAuditPage(DATA_DIR, { categories: ["computer"], target: computerId, limit }).rows;
    const switches = readOrgAuditPage(DATA_DIR, { categories: ["computer"], limit: 500, from: Date.now() - 30 * 24 * 60 * 60_000 }).rows.filter((row) =>
      row.action === "computer.switch" && row.actor.kind === "person" && row.actor.principalId === principalId
      && (surfaces.includes(String(row.after?.computer)) || surfaces.includes(String(row.before?.computer))));
    return [...own, ...switches].sort((a, b) => Date.parse(b.at) - Date.parse(a.at)).slice(0, limit).map((row) => wireAuditRow(row, adminPerson));
  },
};

/** A reachability check of an address an admin configured (an MCP server,
 * a marketplace): any HTTP answer below 500 means it is up. No credential
 * is sent; redirects are not followed. */
async function reachable(url: string): Promise<TestResult> {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, reason: "bad_address", label: "The address is not a URL." };
  }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return { ok: false, reason: "bad_address", label: "Only http and https addresses can be tested." };
  try {
    const res = await fetch(parsed, { method: "GET", redirect: "manual", signal: AbortSignal.timeout(8_000) });
    await res.body?.cancel().catch(() => {});
    return res.status < 500 ? { ok: true, reason: null, label: null } : { ok: false, reason: "http_error", label: `The server answered ${res.status}.` };
  } catch (error) {
    return { ok: false, reason: "unreachable", label: redactSecretsInText(error instanceof Error ? (error.cause instanceof Error ? error.cause.message : error.message) : String(error)).slice(0, 300) };
  }
}

/** The organization's MCP servers (config.json), as names and transports. */
function orgMcpServers(): Array<{ name: string; transport: "remote" | "stdio"; url: string | null; enabled: boolean }> {
  return Object.entries(cfg.mcpServers ?? {}).map(([name, raw]) => {
    const value = raw && typeof raw === "object" ? raw as Record<string, unknown> : {};
    const url = typeof value.url === "string" ? value.url : null;
    return { name, transport: url ? "remote" as const : "stdio" as const, url, enabled: value.disabled !== true && value.enabled !== false };
  }).sort((a, b) => a.name.localeCompare(b.name));
}

/** The console's Connections, Logs, Incidents and Settings (server/org-admin-ops.ts). */
const orgOpsDeps: OpsDeps = {
  connections: async (): Promise<ConnectionsView> => {
    const people = orgPeopleDeps.people().filter((person) => !person.perspicaxDisabled && !person.consoleDisabled);
    const engines = registry.entries().map((entry) => {
      const driver = entry.shadow?.driverKind ?? entry.live?.driverKind ?? "";
      return {
        id: entry.instanceId,
        name: engineDisplayName(entry.live ?? entry.shadow),
        installed: engineInstalled(entry.instanceId),
        version: engineProbes.get(entry.instanceId)?.version ?? null,
        orgKey: driverKeyBacked(cfg, driver, entry.instanceId),
        people: people.filter((person) => person.engines.some((engine) => engine.id === entry.instanceId && engine.via !== "none")).length,
      };
    });
    const mcpServers: ConnectionsView["mcpServers"] = orgMcpServers().map((server) => ({
      id: server.name, name: server.name, scope: "org" as const, owner: null, transport: server.transport, state: server.enabled ? "enabled" : "disabled",
    }));
    for (const person of people) {
      for (const [name, server] of Object.entries(personConnections.servers(person.principalId))) {
        mcpServers.push({ id: name, name, scope: "person", owner: adminPerson(person.principalId), transport: server.kind === "stdio" ? "stdio" : "remote", state: server.enabled ? "enabled" : "disabled" });
      }
    }
    const policy = pluginMarketplacePolicy();
    const library = skillsLibraryEnabled(cfg) ? listLibrarySkills() : [];
    return {
      engines,
      people: people.map((person) => ({
        person: adminPerson(person.principalId),
        engines: person.engines.map((engine) => ({ id: engine.id, via: engine.via, ok: null, checkedAt: null })),
        mcpServers: Object.keys(personConnections.servers(person.principalId)).length,
      })),
      mcpServers,
      marketplaces: pluginMarketplaces.list().map((market) => {
        let allowed = true;
        try {
          allowed = marketplaceAllowed(policy, parseGitSource(market.source, market.ref));
        } catch {
          allowed = false;
        }
        return { id: market.name, name: market.name, url: market.source, allowed, plugins: market.plugins.length };
      }),
      skills: library.map((skill) => ({
        id: skill.name, name: skill.name, source: skill.source || null, version: skill.sha256 ? skill.sha256.slice(0, 12) : null,
        bots: store.bots.filter((bot) => bot.assignedSkills?.includes(skill.name)).length,
      })),
    };
  },
  test: async (kind, id, principalId) => {
    if (kind === "engine") {
      const live = registry.get(id);
      if (!live) return { ok: false, reason: "engine_not_installed", label: `No engine ${id} on this server.` };
      const snapshot = await live.snapshot();
      if (snapshot.state !== "available") return { ok: false, reason: "engine_unavailable", label: redactSecretsInText(snapshot.reason ?? "The engine is not available.").slice(0, 300) };
      if (principalId) {
        const access = personEngineAccess(principalId).find((engine) => engine.id === id);
        if (!access || access.via === "none") return { ok: false, reason: "no_access", label: "This person has no access to this engine (no subscription, no key, no organization key)." };
      } else if (snapshot.authenticated === false && !driverKeyBacked(cfg, live.driverKind, id)) {
        return { ok: false, reason: "auth", label: "The engine is installed but not signed in, and the organization has no key for it." };
      }
      return { ok: true, reason: null, label: null };
    }
    if (kind === "mcp") {
      if (principalId) {
        const own = personConnections.servers(principalId)[id];
        if (!own) return { ok: false, reason: "not_found", label: "No MCP server with that name." };
        if (own.kind !== "stdio") return reachable(own.url);
        // A person's command runs in their server environment, never here.
        if (!userSandbox) return { ok: false, reason: "no_environment", label: "This server has no server environments: a person's command cannot be started to test it." };
        const sandbox = userSandbox;
        return testStdioMcpStream(() => sandbox.stdioStream(principalId, { argv: [own.command, ...own.args], env: own.env }), own);
      }
      const server = orgMcpServers().find((candidate) => candidate.name === id);
      if (!server) return { ok: false, reason: "not_found", label: "No MCP server with that name." };
      if (server.url) return reachable(server.url);
      const parsed = parseStoredMcpServer(id, cfg.mcpServers?.[id]);
      if (!parsed.ok || isRemoteMcpServer(parsed.server)) return { ok: false, reason: "invalid", label: "This server's saved settings are not valid." };
      return testStdioMcpCommand(parsed.server);
    }
    if (kind === "marketplace") {
      const market = pluginMarketplaces.list().find((candidate) => candidate.name === id);
      if (!market) return { ok: false, reason: "not_found", label: "No marketplace with that name." };
      const source = market.source.trim();
      return reachable(/^[\w.-]+\/[\w.-]+$/.test(source) ? `https://github.com/${source}` : source);
    }
    return { ok: false, reason: "unknown_kind", label: null };
  },
  logs: (input) => serverLog.read(input),
  problems: (from) => readProblems(DATA_DIR, { from }),
  botsOwnedBy: (principalId) => store.bots.filter((bot) => effectiveBotOwner(bot) === principalId).map((bot) => bot.id),
  settings: () => {
    const selection = cfg.newBotDefaults?.profile.modelSelection ?? cfg.defaultModelSelection;
    const policy = pluginMarketplacePolicy();
    const backup = readBackupStatus(process.env.SAGAX_BACKUP_STATUS_FILE?.trim() || join(DATA_DIR, "backup-status.json"));
    return {
      org: orgSettings(),
      policies: {
        allowedMarketplaces: policy?.mode === "list" ? [...policy.allow] : null,
        allowedEngines: cfg.organization?.allowedEngines ? [...cfg.organization.allowedEngines] : null,
        ownAccountsOutsideList: cfg.organization?.ownAccountsOutsideList === true,
        // 2026-10-30 (lot 2): per model, `<engine>/<model>`, and each engine's models to switch
        disabledModels: orgDisabledModels(),
        engineModels: Object.fromEntries(registry.instances().map((instance) => [instance.instanceId,
          instance.models.options.filter((option) => !option.local).map((option) => ({ id: option.id, label: option.label || option.id }))])),
        defaults: { engine: selection?.instanceId ?? null, model: selection?.model ?? null, approvalMode: cfg.newBotDefaults?.profile.approvalMode ?? null },
      },
      backup,
    };
  },
  saveSettings: (changes, adminPrincipalId) => {
    const actor: AdminActor = { kind: "person", principalId: adminPrincipalId, via: "console" };
    if (changes.allowedEngines !== undefined) {
      const unknown = (changes.allowedEngines ?? []).find((id) => !registry.entries().some((entry) => entry.instanceId === id));
      if (unknown) throw new ConsoleRefusal(400, "engine_not_installed", `No engine ${unknown} on this server.`);
    }
    if (changes.defaults && (changes.defaults.engine !== undefined || changes.defaults.model !== undefined)) {
      const current = cfg.newBotDefaults?.profile.modelSelection ?? cfg.defaultModelSelection;
      const instanceId = changes.defaults.engine ?? current?.instanceId;
      const model = changes.defaults.model ?? (instanceId === current?.instanceId ? current?.model : registry.get(instanceId ?? "")?.models.default);
      if (!instanceId || !model) throw new ConsoleRefusal(400, "bad_request", "Name the default engine and model.");
      const checked = checkedModelSelection({ instanceId, model }, undefined, true);
      if (!checked.ok) throw new ConsoleRefusal(checked.status, "bad_request", checked.error);
    }
    try {
      if (changes.pluginMarketplaces) saveOrgPluginMarketplaces(changes.pluginMarketplaces, actor);
    } catch (error) {
      if (error instanceof OrgSettingOwnedElsewhere) throw new ConsoleRefusal(409, error.code, error.message);
      throw new ConsoleRefusal(400, "invalid_policy", error instanceof Error ? error.message : "That marketplace list is not valid.");
    }
    if (changes.allowFullAccess !== undefined) saveOrgAllowFullAccess(changes.allowFullAccess, actor);
    if (changes.memberEnvironmentAutonomy !== undefined) saveOrgMemberEnvironmentAutonomy(changes.memberEnvironmentAutonomy, actor);
    if (changes.memberAutoApproval !== undefined) saveOrgMemberAutoApproval(changes.memberAutoApproval, actor);
    if (changes.allowVaultExport !== undefined) saveOrgAllowVaultExport(changes.allowVaultExport, actor);
    if (changes.interimAttachDays !== undefined) saveOrgInterimAttachDays(changes.interimAttachDays, actor);
    if (changes.allowedEngines !== undefined) {
      const before = cfg.organization?.allowedEngines ?? null;
      const organization = { ...cfg.organization };
      if (changes.allowedEngines) organization.allowedEngines = changes.allowedEngines;
      else delete organization.allowedEngines;
      saveConfig({ organization });
      cfg.organization = organization;
      orgAudit({ category: "org", action: "org.settings", target: { kind: "organization" }, changed: ["allowedEngines"], before: { allowedEngines: before }, after: { allowedEngines: changes.allowedEngines }, actor });
      applyOrgEngineAllowList();
      // Every open picker lists the new set at once (config frame).
      broadcast({ kind: "config", ...configStatus() });
    }
    if (changes.disabledModels !== undefined) {
      // 2026-10-30 (lot 2): models off for everyone, admins included
      const before = orgDisabledModels();
      const organization = { ...cfg.organization };
      if (changes.disabledModels.length) organization.disabledModels = changes.disabledModels;
      else delete organization.disabledModels;
      saveConfig({ organization });
      cfg.organization = organization;
      orgAudit({ category: "org", action: "org.settings", target: { kind: "organization" }, changed: ["disabledModels"], before: { disabledModels: before }, after: { disabledModels: changes.disabledModels }, actor });
      applyModelSwitches();
      broadcast({ kind: "config", ...configStatus() });
    }
    if (changes.ownAccountsOutsideList !== undefined) {
      // 2026-10-30: own subscriptions and keys outside the list, off by default
      const before = cfg.organization?.ownAccountsOutsideList === true;
      const organization = { ...cfg.organization };
      if (changes.ownAccountsOutsideList) organization.ownAccountsOutsideList = true;
      else delete organization.ownAccountsOutsideList;
      saveConfig({ organization });
      cfg.organization = organization;
      orgAudit({ category: "org", action: "org.settings", target: { kind: "organization" }, changed: ["ownAccountsOutsideList"], before: { ownAccountsOutsideList: before }, after: { ownAccountsOutsideList: changes.ownAccountsOutsideList }, actor });
      // Turned off: a bot kept on its owner's own engine moves to Auto now.
      applyOrgEngineAllowList();
      broadcast({ kind: "config", ...configStatus() });
    }
    if (changes.defaults) {
      const current = cfg.newBotDefaults?.profile.modelSelection ?? cfg.defaultModelSelection;
      const instanceId = changes.defaults.engine ?? current?.instanceId;
      const model = changes.defaults.model ?? (instanceId === current?.instanceId ? current?.model : registry.get(instanceId ?? "")?.models.default);
      const profile = { ...cfg.newBotDefaults?.profile } as Record<string, unknown>;
      if (instanceId && model && (changes.defaults.engine !== undefined || changes.defaults.model !== undefined)) profile.modelSelection = { instanceId, model };
      if (changes.defaults.approvalMode !== undefined) {
        if (changes.defaults.approvalMode) profile.approvalMode = changes.defaults.approvalMode;
        else delete profile.approvalMode;
      }
      const next = newBotDefaultsSchema.parse({ ...cfg.newBotDefaults, profile });
      const before = { engine: current?.instanceId ?? null, model: current?.model ?? null, approvalMode: cfg.newBotDefaults?.profile.approvalMode ?? null };
      saveConfig({ newBotDefaults: next });
      cfg.newBotDefaults = next;
      const after = next.profile.modelSelection;
      orgAudit({
        category: "org", action: "org.settings", target: { kind: "organization" }, changed: ["defaults"], before,
        after: { engine: after?.instanceId ?? null, model: after?.model ?? null, approvalMode: next.profile.approvalMode ?? null }, actor,
      });
    }
  },
  now: Date.now,
};

/** Slice 8: shorten, extend (at most 90 days from when it opened) or close
 * the window to attach people from before Perspicax. */
function saveOrgInterimAttachDays(days: number, actor: AdminActor): void {
  const before = cfg.organization?.interimAttach;
  const next = windowWithDays(before, days, Date.now());
  saveConfig({ organization: { ...cfg.organization, interimAttach: next } });
  cfg.organization = { ...cfg.organization, interimAttach: next };
  orgAudit({
    category: "org", action: "org.settings", target: { kind: "organization" }, changed: ["interimAttachDays"],
    before: { interimAttachDays: before?.days ?? null }, after: { interimAttachDays: days }, actor,
  });
}
